B.arT=new A.b("gen_ai_special_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59(\uc81c4\uc870)","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Qv,0,"\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\ub824\uba74 \ub2e8\uc21c\ud788 \uc11c\ub958\uc0c1 \ubcc4\ub3c4 \uc870\ud56d\uc774 \uc788\ub2e4\ub294 \ud615\uc2dd\ubcf4\ub2e4, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc57d\uad00\uacfc \ub2e4\ub978 \ub0b4\uc6a9\uc5d0 \uad00\ud558\uc5ec \uc2e4\uc9c8\uc801\uc778 \uad50\uc12d\uacfc \ud569\uc758\uac00 \uc774\ub8e8\uc5b4\uc84c\ub2e4\uace0 \uc778\uc815\ub420 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uacc4\uc57d\uc11c\uc0c1 \uc704\uce58, \uacf5\uc99d \uc5ec\ubd80, \uc0ac\uc5c5\uc790 \ub2e8\ub3c5 \uc791\uc131 \uc5ec\ubd80\ub294 \uac1c\ubcc4\uc57d\uc815 \uc778\uc815\uc758 \ubcf8\uc9c8\uc801 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4.",B.I_,B.adC,null)
B.acP=s([u.sd,"\uac1c\ubcc4\uc57d\uc815\uc740 \uadf8 \ub0b4\uc6a9\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc720\ud6a8\ud558\uac8c \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc774 \ubd88\ub9ac\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \uc57d\uad00 \ub0b4\uc6a9\uc774 \ubd80\ud65c\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc740 \uace0\uac1d\uc5d0\uac8c \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc744 \uc815\ud560 \uc218 \uc5c6\ub3c4\ub85d \ubc95\ub960\uc0c1 \uc804\uba74 \uae08\uc9c0\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc758 \ubd88\ub9ac\ud55c \uc815\ub3c4\ub294 \ud310\ub2e8 \uae30\uc900\uc5d0\uc11c \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.IQ=s([u.sd],t.s)
B.afh=s(["\uac1c\ubcc4\uc57d\uc815\uc758 \ud55c\uacc4"],t.s)
B.ayM=new A.b("gen_ai_special_3","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59(\uc81c4\uc870)","\uac1c\ubcc4\uc57d\uc815\uc774 \uace0\uac1d\uc5d0\uac8c \uc57d\uad00\ubcf4\ub2e4 \ubd88\ub9ac\ud55c \ub0b4\uc6a9\uc77c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.acP,0,"\uac1c\ubcc4\uc57d\uc815\uc774 \uc57d\uad00\ubcf4\ub2e4 \uc6b0\uc120\ud55c\ub2e4\ub294 \uc6d0\uce59\uc774 \uc788\ub354\ub77c\ub3c4, \uadf8 \uac1c\ubcc4\uc57d\uc815 \uc790\uccb4\uc758 \ub0b4\uc6a9\uc774 \uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\uac70\ub098 \uc57d\uad00\ubc95\uc774 \uc815\ud558\ub294 \ubb34\ud6a8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud560 \uc815\ub3c4\ub85c \ubd88\uacf5\uc815\ud558\ub2e4\uba74, \uac1c\ubcc4\uc57d\uc815 \uc5ed\uc2dc \ubcc4\ub3c4\ub85c \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4. \uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \ubaa8\ub4e0 \ub0b4\uc6a9\ud1b5\uc81c\ub97c \ubc30\uc81c\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.IQ,B.afh,null)
B.adT=s([u.lk,"\uc774 \uc6d0\uce59\uc740 \uc0ac\uc5c5\uc790\uc758 \uc774\uc775\ub9cc\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc774 \uc6d0\uce59\uc740 \uc57d\uad00\ubc95\uc758 \ub2e4\ub978 \uaddc\uc815\ub4e4\uc744 \uc804\ubd80 \ubb34\ub825\ud654\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc774 \uc6d0\uce59\uc740 \uace0\uac1d\uc5d0\uac8c \uc5b4\ub5a0\ud55c \uc774\uc775\ub3c4 \uc8fc\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uc6d0\uce59\uc740 \uc624\uc9c1 \uad6d\uc81c\uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.a5Y=s([u.lk],t.s)
B.aje=s(["\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120 \uc6d0\uce59\uc758 \uc758\uc758"],t.s)
B.au8=new A.b("gen_ai_special_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59(\uc81c4\uc870)","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc774 \uc2e4\ubb34\uc0c1 \uac00\uc9c0\ub294 \uc758\uc758\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.adT,0,"\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \uc57d\uad00\uc774\ub77c\ub294 \uc815\ud615\uc801\xb7\uc77c\ubc29\uc801 \uacc4\uc57d\ub0b4\uc6a9\ubcf4\ub2e4 \ub2f9\uc0ac\uc790\uac00 \uc2e4\uc81c\ub85c \ud611\uc758\ud558\uc5ec \ud569\uc758\ud55c \ub0b4\uc6a9\uc744 \uc6b0\uc120\uc2dc\ud568\uc73c\ub85c\uc368, \uc57d\uad00\uc5d0 \ub300\ud55c \ub0b4\uc6a9\ud1b5\uc81c\uc640 \uacc4\uc57d\uc790\uc720\uc758 \uc6d0\uce59(\uc0ac\uc801\uc790\uce58) \uc0ac\uc774\uc758 \uc870\ud654\ub97c \ub3c4\ubaa8\ud558\ub294 \uc2e4\ubb34\uc801 \uc758\uc758\ub97c \uac00\uc9c4\ub2e4.",B.a5Y,B.aje,null)
B.aaO=s([u.lz,"\uc644\uc804\ud569\uc758\uc870\ud56d\uc774 \uc788\uc73c\uba74 \uc5b4\ub5a0\ud55c \uac1c\ubcc4 \uad6c\ub450\ud569\uc758\ub3c4 \uc608\uc678 \uc5c6\uc774 \ubb34\ud6a8\uc774\ub2e4","\uc644\uc804\ud569\uc758\uc870\ud56d\uc740 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ubbc0\ub85c \uc804\ud600 \uace0\ub824\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uc644\uc804\ud569\uc758\uc870\ud56d\uc774 \uc788\uc73c\uba74 \uc57d\uad00\ubc95 \uc790\uccb4\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc644\uc804\ud569\uc758\uc870\ud56d\uc758 \ud6a8\ub825\uc740 \ubc95\uc6d0\uc758 \ud310\ub2e8\uacfc \ubb34\uad00\ud558\uac8c \uc808\ub300\uc801\uc774\ub2e4"],t.s)
B.agH=s([u.lz],t.s)
B.a15=s(["\uc644\uc804\ud569\uc758\uc870\ud56d\uacfc \uac1c\ubcc4\uc57d\uc815"],t.s)
B.az5=new A.b("gen_ai_special_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59(\uc81c4\uc870)",'\uacc4\uc57d\uc11c\uc5d0 "\ubcf8 \uacc4\uc57d\uacfc \ub2e4\ub978 \uad6c\ub450\uc0c1 \ud569\uc758\ub294 \ud6a8\ub825\uc774 \uc5c6\ub2e4"\ub294 \uc870\ud56d(\uc644\uc804\ud569\uc758\uc870\ud56d)\uc774 \uc788\ub294 \uacbd\uc6b0, \uc2e4\uc81c\ub85c \uc774\ub8e8\uc5b4\uc9c4 \uac1c\ubcc4 \uad6c\ub450\ud569\uc758\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aaO,0,"\uc644\uc804\ud569\uc758\uc870\ud56d(\ub2e4\ub978 \ud569\uc758\ub294 \ud6a8\ub825\uc774 \uc5c6\ub2e4\ub294 \ucde8\uc9c0\uc758 \uc57d\uad00\uc870\ud56d) \uc790\uccb4\ub3c4 \ud558\ub098\uc758 \uc57d\uad00\uc870\ud56d\uc73c\ub85c\uc11c \uc2ec\uc0ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\uc73c\uba70, \uc2e4\uc81c\ub85c \uac1c\ubcc4\uc57d\uc815\uc774\ub77c\uace0 \ubcfc \uc218 \uc788\ub294 \uc0ac\uc815\uc774 \uc778\uc815\ub41c\ub2e4\uba74 \uadf8\ub7ec\ud55c \uc870\ud56d\uc758 \uc874\uc7ac\ub9cc\uc73c\ub85c \uadf8 \ud6a8\ub825\uc774 \ub2f9\uc5f0\ud788 \ubc30\uc81c\ub41c\ub2e4\uace0 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\ub2e4\ub294 \uac83\uc774 \uc77c\ubc18\uc801 \ub17c\uc758\uc774\ub2e4. \uad6c\uccb4\uc801 \uacb0\ub860\uc740 \uc0ac\uc548\uc758 \uc0ac\uc815\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9c8 \uc218 \uc788\ub2e4.",B.agH,B.a15,null)
B.Y0=s([u.ai,"\uac1c\ubcc4\uc57d\uc815\uc5d0\ub3c4 \uc57d\uad00\uc758 \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\uac00 \uc544\ubb34 \ucc28\uc774 \uc5c6\uc774 \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc740 \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\uc640 \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc624\ud788\ub824 \uc57d\uad00\ubcf4\ub2e4 \ub354 \uc5c4\uaca9\ud55c \uc124\uba85\uc758\ubb34\uac00 \ubd80\uacfc\ub41c\ub2e4","\uac1c\ubcc4\uc57d\uc815\uacfc \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\ub294 \uc11c\ub85c \ubc18\ub300\ub418\ub294 \uac1c\ub150\uc73c\ub85c \ub3d9\uc2dc\uc5d0 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub2e4","\uac1c\ubcc4\uc57d\uc815\uc774 \uc778\uc815\ub418\uba74 \uacc4\uc57d \uc790\uccb4\uac00 \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.ae2=s([u.ai],t.s)
B.PH=s(["\uac1c\ubcc4\uc57d\uc815\uacfc \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\uc758 \uad00\uacc4"],t.s)
B.as4=new A.b("gen_ai_special_6","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59(\uc81c4\uc870)","\uac1c\ubcc4\uc57d\uc815 \uc6b0\uc120\uc758 \uc6d0\uce59\uacfc \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Y0,0,"\uc57d\uad00\uc758 \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\ub294 \uc0ac\uc5c5\uc790\uac00 \uc77c\ubc29\uc801\uc73c\ub85c \ub9c8\ub828\ud55c \uc815\ud615\uc801 \uc57d\uad00\uc870\ud56d\uc744 \uace0\uac1d\uc774 \uc778\uc9c0\ud558\uc9c0 \ubabb\ud55c \ucc44 \uacc4\uc57d\ub0b4\uc6a9\uc774 \ub418\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uac83\uc778 \ubc18\uba74, \uac1c\ubcc4\uc57d\uc815\uc740 \ub2f9\uc0ac\uc790 \uac04 \uc2e4\uc9c8\uc801 \uad50\uc12d\uc744 \uac70\uccd0 \uc131\ub9bd\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ud1b5\uc0c1\uc801\uc778 \uc57d\uad00\uc5d0 \ub300\ud55c \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34 \ubc95\ub9ac\uac00 \uadf8\ub300\ub85c \uc801\uc6a9\ub418\ub294 \uc870\ud56d\uacfc\ub294 \uc131\uaca9\uc744 \ub2ec\ub9ac\ud55c\ub2e4\uace0 \uc774\ud574\ub41c\ub2e4.",B.ae2,B.PH,null)
B.aik=s([u.xi,"\uc57d\uad00\uc740 \uc624\uc9c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c\ub9cc \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc57d\uad00\uc740 \uac01 \uace0\uac1d\uc758 \uac1c\ubcc4 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc11c\ub85c \ub2e4\ub974\uac8c \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc57d\uad00 \ud574\uc11d\uc740 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uacfc \uc804\ud600 \ubb34\uad00\ud558\uac8c \uc0ac\uc5c5\uc790\uac00 \uc815\ud55c \ub300\ub85c\ub9cc \uc774\ub8e8\uc5b4\uc9c4\ub2e4","\uc57d\uad00\uc740 \ud574\uc11d\uc758 \uc5ec\uc9c0 \uc5c6\uc774 \ubb38\uc5b8 \uadf8\ub300\ub85c\ub9cc \uae30\uacc4\uc801\uc73c\ub85c \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.agY=s([u.xi],t.s)
B.Sl=s(["\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\uc758 \uc6d0\uce59"],t.s)
B.azO=new A.b("gen_ai_good_1","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)","\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960 \uc81c5\uc870 \uc81c1\ud56d\uc774 \uc815\ud558\ub294 \uc57d\uad00 \ud574\uc11d\uc758 \uc6d0\uce59\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aik,0,"\uc57d\uad00\ubc95 \uc81c5\uc870 \uc81c1\ud56d\uc740 \uc57d\uad00\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc5d0 \ub530\ub77c \uacf5\uc815\ud558\uac8c \ud574\uc11d\ub418\uc5b4\uc57c \ud558\uba70, \uace0\uac1d\uc5d0 \ub530\ub77c \ub2e4\ub974\uac8c \ud574\uc11d\ub418\uc5b4\uc11c\ub294 \uc548 \ub41c\ub2e4\ub294 \uc6d0\uce59\uc744 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub418\ub294 \uc57d\uad00\uc758 \ud2b9\uc131\uc0c1 \ud1b5\uc77c\uc801\uc774\uace0 \uac1d\uad00\uc801\uc778 \ud574\uc11d\uc774 \uc774\ub8e8\uc5b4\uc838\uc57c \ud55c\ub2e4\ub294 \ucde8\uc9c0\uc774\ub2e4.",B.agY,B.Sl,null)
B.Jd=s([u.Ct,"\ud1b5\uc77c\uc801 \ud574\uc11d\uc740 \uc0ac\uc5c5\uc790\uc758 \ud3b8\uc758\ub9cc\uc744 \uc704\ud55c \uac83\uc774\ub2e4","\ud1b5\uc77c\uc801 \ud574\uc11d\uc740 \uc624\uc9c1 \ubc95\uc6d0\uc758 \uc5c5\ubb34 \ubd80\ub2f4\uc744 \uc904\uc774\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\ud1b5\uc77c\uc801 \ud574\uc11d\uc740 \uc57d\uad00\ubc95\uacfc \ubb34\uad00\ud55c \uc808\ucc28\ubc95\uc0c1 \uc6d0\uce59\uc774\ub2e4","\ud1b5\uc77c\uc801 \ud574\uc11d\uc740 \uace0\uac1d\uc758 \uac1c\ubcc4 \uc0ac\uc815\uc744 \ucd5c\uc6b0\uc120\uc73c\ub85c \ubc18\uc601\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4"],t.s)
B.adN=s([u.Ct],t.s)
B.a5I=s(["\ud1b5\uc77c\uc801 \ud574\uc11d\uc758 \ud544\uc694\uc131"],t.s)
B.ayx=new A.b("gen_ai_good_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)",'\uc57d\uad00\uc758 "\ud1b5\uc77c\uc801 \ud574\uc11d"\uc774 \uc694\uad6c\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.Jd,0,"\uc57d\uad00\uc740 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub418\ub294 \uac83\uc744 \uc804\uc81c\ub85c \ud558\ubbc0\ub85c, \ub3d9\uc77c\ud55c \uc870\ud56d\uc774 \uace0\uac1d\ub9c8\ub2e4 \ub2e4\ub974\uac8c \ud574\uc11d\ub41c\ub2e4\uba74 \ubc95\uc801 \uc548\uc815\uc131\uacfc \uace0\uac1d \uac04 \ud615\ud3c9\uc131\uc774 \ud06c\uac8c \uc800\ud574\ub420 \uc218 \uc788\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc57d\uad00\ubc95\uc740 \uac1c\ubcc4 \uace0\uac1d\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uc5d0 \uc88c\uc6b0\ub418\uc9c0 \uc54a\ub294 \uac1d\uad00\uc801\xb7\ud1b5\uc77c\uc801 \ud574\uc11d\uc744 \uc694\uad6c\ud55c\ub2e4.",B.adN,B.a5I,null)
B.a9V=s([u.yB,"\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \uc624\uc9c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uc758\ubb34\uc774\ub2e4","\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \uc57d\uad00 \ud574\uc11d\uacfc \ubb34\uad00\ud55c \ud615\ubc95\uc0c1 \uac1c\ub150\uc774\ub2e4","\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \uace0\uac1d\uc758 \uc8fc\uc7a5\uc744 \ud56d\uc0c1 \uadf8\ub300\ub85c \uc778\uc815\ud574\uc57c \ud55c\ub2e4\ub294 \uc758\ubbf8\uc774\ub2e4","\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \uacc4\uc57d\uc11c\uc5d0 \uba85\uc2dc\ub418\uc5b4\uc57c\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.Nf=s([u.yB],t.s)
B.a3K=s(["\uc2e0\uc758\uc131\uc2e4 \uc6d0\uce59\uc758 \uc758\ubbf8"],t.s)
B.atq=new A.b("gen_ai_good_3","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)",'\uc57d\uad00 \ud574\uc11d \uc2dc "\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59"\uc774 \uc758\ubbf8\ud558\ub294 \ubc14\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a9V,0,"\uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc740 \uacc4\uc57d \ub2f9\uc0ac\uc790\uac00 \uc0c1\ub300\ubc29\uc758 \uc815\ub2f9\ud55c \uc774\uc775\uc744 \uace0\ub824\ud558\uc5ec \ud615\ud3c9\uc5d0 \ub9de\uac8c \ud589\ub3d9\ud574\uc57c \ud55c\ub2e4\ub294 \ubbfc\ubc95\uc758 \uc77c\ubc18\uc6d0\uce59\uc73c\ub85c, \uc57d\uad00 \ud574\uc11d\uc5d0\uc11c\ub3c4 \uc0ac\uc5c5\uc790\uc640 \uace0\uac1d \uc5b4\ub290 \uc77c\ubc29\uc758 \uc774\uc775\uc5d0 \uce58\uc6b0\uce58\uc9c0 \uc54a\uace0 \uc30d\ubc29\uc758 \uc774\uc775\uc744 \uacf5\uc815\ud558\uac8c \ud615\ub7c9\ud558\uc5ec \ud574\uc11d\ud574\uc57c \ud55c\ub2e4\ub294 \uc758\ubbf8\ub85c \uc801\uc6a9\ub41c\ub2e4.",B.Nf,B.a3K,null)
B.a4p=s([u.zH,"\ud574\uc11d\uc740 \uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \uc8fc\uad00\uc801 \uc758\ub3c4\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4","\ud574\uc11d\uc740 \uc624\uc9c1 \uac00\uc7a5 \uc9c0\uc2dd\uc774 \ub9ce\uc740 \uc804\ubb38\uac00 \uace0\uac1d\uc758 \uad00\uc810\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4","\ud574\uc11d\uc740 \ub9e4\ubc88 \uac1c\ubcc4 \uace0\uac1d\uc758 \uc774\ud574\uc218\uc900\uc5d0 \ub9de\ucd94\uc5b4 \ub2ec\ub77c\uc9c4\ub2e4","\ubd88\uba85\ud655\ud55c \uc870\ud56d\uc740 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ub41c\ub2e4"],t.s)
B.WB=s([u.zH],t.s)
B.afi=s(["\ud3c9\uade0\uc801 \uace0\uac1d \uae30\uc900 \ud574\uc11d"],t.s)
B.az7=new A.b("gen_ai_good_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)","\uc57d\uad00 \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \ubd88\uba85\ud655\ud55c \uacbd\uc6b0 \ud574\uc11d \ubc29\ubc95\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a4p,0,"\uc57d\uad00 \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \ubd88\uba85\ud655\ud55c \uacbd\uc6b0\uc5d0\ub294 \ud2b9\uc815 \uac1c\uc778\uc774 \uc544\ub2c8\ub77c \ud3c9\uade0\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \uace0\uac1d\uc774 \uadf8 \uc870\ud56d\uc744 \uc5b4\ub5bb\uac8c \uc774\ud574\ud560 \uac83\uc778\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \uac1d\uad00\uc801\uc774\uace0 \ud1b5\uc77c\uc801\uc73c\ub85c \ud574\uc11d\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub418\ub294 \uc57d\uad00\uc758 \uc131\uaca9\uc5d0 \ubd80\ud569\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.",B.WB,B.afi,null)
B.Lu=s([u.EV,"\uc774\ub7ec\ud55c \uac00\ub2a5\uc131\uc740 \ud1b5\uc77c\uc801 \ud574\uc11d \uc6d0\uce59\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\ubc95\uc6d0\uc740 \ub3d9\uc77c \uc870\ud56d\uc5d0 \ub300\ud574 \ud56d\uc0c1 \uae30\uacc4\uc801\uc73c\ub85c \ub3d9\uc77c\ud55c \uacb0\ub860\ub9cc \ub0b4\ub824\uc57c \ud558\uba70 \uc0ac\uc2e4\uad00\uacc4\ub294 \uc804\ud600 \uace0\ub824\ud558\uc9c0 \uc54a\ub294\ub2e4","\ud1b5\uc77c\uc801 \ud574\uc11d \uc6d0\uce59\uc774 \uc788\uc73c\ubbc0\ub85c \ubc95\uc6d0\uc758 \ud310\ub2e8\uc740 \uc808\ub300\ub85c \ub2ec\ub77c\uc9c8 \uc218 \uc5c6\ub2e4","\uc774 \ubb38\uc81c\ub294 \uc57d\uad00\ubc95\uacfc \ubb34\uad00\ud55c \uc18c\uc1a1\ubc95\uc0c1 \ubb38\uc81c\uc77c \ubfd0\uc774\ub2e4"],t.s)
B.akI=s([u.EV],t.s)
B.a24=s(["\ud1b5\uc77c\uc801 \ud574\uc11d\uacfc \uac1c\ubcc4 \uc0ac\uc548\uc758 \uad00\uacc4"],t.s)
B.aAg=new A.b("gen_ai_good_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)","\ub3d9\uc77c\ud55c \uc57d\uad00 \uc870\ud56d\uc5d0 \ub300\ud574 \uc11c\ub85c \ub2e4\ub978 \uc18c\uc1a1\uc5d0\uc11c \ubc95\uc6d0\uc774 \ub2e4\ub974\uac8c \ud310\ub2e8\ud560 \uac00\ub2a5\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Lu,0,'\ud1b5\uc77c\uc801 \ud574\uc11d\uc758 \uc6d0\uce59\uc740 \ub3d9\uc77c\ud55c \uc57d\uad00 \uc870\ud56d\uc758 "\uc758\ubbf8" \uc790\uccb4\ub97c \uace0\uac1d\uc5d0 \ub530\ub77c \uc790\uc758\uc801\uc73c\ub85c \ub2ec\ub9ac \ud574\uc11d\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4\ub294 \uac83\uc774\uc9c0, \uad6c\uccb4\uc801 \uc0ac\uac74\ub9c8\ub2e4 \ub2e4\ub978 \uc0ac\uc2e4\uad00\uacc4(\uacc4\uc57d\uacbd\uc704, \ud2b9\uc57d \uc874\ubd80 \ub4f1)\uae4c\uc9c0 \uc644\uc804\ud788 \ubb34\uc2dc\ud558\uace0 \ud56d\uc0c1 \ub3d9\uc77c\ud55c \uacb0\ub860\uc744 \ub0b4\ub824\uc57c \ud55c\ub2e4\ub294 \uc758\ubbf8\ub294 \uc544\ub2c8\ub2e4. \ub2e4\ub9cc \uc870\ud56d\uc758 \ud574\uc11d \uc790\uccb4\uac00 \uc0ac\uc548\ub9c8\ub2e4 \ub2ec\ub77c\uc9c0\ub294 \uac83\uc740 \ud1b5\uc77c\uc801 \ud574\uc11d\uc758 \ucde8\uc9c0\uc5d0 \ube44\ucd94\uc5b4 \ubc14\ub78c\uc9c1\ud558\uc9c0 \uc54a\ub2e4.',B.akI,B.a24,null)
B.Jz=s([u.o0,"\uc81c5\uc870\uc640 \uc81c6\uc870~\uc81c14\uc870\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \uc911\ubcf5 \uaddc\uc815\ud55c \uac83\uc774\ub2e4","\uc81c5\uc870\uac00 \uc801\uc6a9\ub418\uba74 \uc81c6\uc870~\uc81c14\uc870\ub294 \uc801\uc6a9\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4","\uc81c6\uc870~\uc81c14\uc870\uac00 \uc801\uc6a9\ub418\uba74 \uc81c5\uc870\ub294 \uc804\ufffd\ud5a5 \ubd88\ud544\uc694\ud558\ub2e4","\ub450 \uaddc\uc815\uc740 \uc11c\ub85c \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubc95\ub960\uc5d0 \uc18d\ud55c\ub2e4"],t.s)
B.PQ=s([u.o0],t.s)
B.a56=s(["\ud574\uc11d\uaddc\uc815\uacfc \ubb34\ud6a8\uaddc\uc815\uc758 \uad00\uacc4"],t.s)
B.att=new A.b("gen_ai_good_6","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc2e0\uc758\uc131\uc2e4 \ud574\uc11d\xb7\ud1b5\uc77c\uc801 \ud574\uc11d(\uc81c5\uc870 \uc81c1\ud56d)","\uc57d\uad00 \ud574\uc11d\uc5d0 \uad00\ud55c \uc81c5\uc870 \uc81c1\ud56d\uacfc \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d \ubb34\ud6a8\uc0ac\uc720(\uc81c6\uc870~\uc81c14\uc870)\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Jz,0,'\uc81c5\uc870\ub294 \uc57d\uad00 \uc870\ud56d\uc758 \uc758\ubbf8\ub97c \uc5b4\ub5bb\uac8c "\ud574\uc11d"\ud560 \uac83\uc778\uc9c0\uc5d0 \uad00\ud55c \ubc29\ubc95\ub860\uc744 \uaddc\uc815\ud558\ub294 \ubc18\uba74, \uc81c6\uc870\ubd80\ud130 \uc81c14\uc870\uae4c\uc9c0\ub294 \ud574\uc11d\uc744 \uac70\uccd0 \ud655\uc815\ub41c \uc57d\uad00 \uc870\ud56d\uc758 "\ub0b4\uc6a9" \uc790\uccb4\uac00 \ubd88\uacf5\uc815\ud558\uc5ec \ubb34\ud6a8\uc778\uc9c0\ub97c \ud310\ub2e8\ud558\ub294 \uaddc\uc815\uc774\ub2e4. \uc2e4\ubb34\uc0c1 \uba3c\uc800 \ud574\uc11d\uc744 \ud1b5\ud574 \uc870\ud56d\uc758 \uc758\ubbf8\ub97c \ud655\uc815\ud55c \ub4a4, \uadf8 \ub0b4\uc6a9\uc774 \ubb34\ud6a8\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\ub97c \uac80\ud1a0\ud558\ub294 \uc21c\uc11c\ub85c \ub450 \uaddc\uc815\uc774 \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4.',B.PQ,B.a56,null)
B.a1U=s(["\uc57d\uad00\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc57d\uad00\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc54a\uc73c\uba74 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ub41c\ub2e4","\uc774 \uc6d0\uce59\uc740 \uc57d\uad00\uc758 \ub73b\uc774 \uba85\ubc31\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud56d\uc0c1 \uc801\uc6a9\ub41c\ub2e4","\uc774 \uc6d0\uce59\uc740 \uace0\uac1d\uc774 \uc0ac\uc5c5\uc790\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uc6d0\uce59\uc740 \uc0ac\uc5c5\uc790\uac00 \uc791\uc131\ud55c \ubaa8\ub4e0 \ubb38\uc11c\uc5d0 \uc608\uc678 \uc5c6\uc774 \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.agO=s(["\uc57d\uad00\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.J6=s(["\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59"],t.s)
B.aqU=new A.b("gen_ai_contra_1","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)",'\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960 \uc81c5\uc870 \uc81c2\ud56d\uc774 \uc815\ud558\ub294 "\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a1U,0,'\uc57d\uad00\ubc95 \uc81c5\uc870 \uc81c2\ud56d\uc740 \uc57d\uad00\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0\uc5d0\ub294 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc774\ub978\ubc14 "\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59"(contra proferentem)\uc744 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc57d\uad00\uc744 \uc77c\ubc29\uc801\uc73c\ub85c \uc791\uc131\ud55c \uc0ac\uc5c5\uc790\uac00 \uadf8 \ubd88\uba85\ud655\uc131\uc5d0 \ub530\ub978 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud558\ub3c4\ub85d \ud558\ub824\ub294 \ucde8\uc9c0\uc774\uba70, \uc57d\uad00\uc758 \uc758\ubbf8\uac00 \uba85\ubc31\ud55c \uacbd\uc6b0\uc5d0\ub294 \ubcc4\ub3c4\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.agO,B.J6,null)
B.II=s([u.Eq,"\uc870\ud56d\uc758 \uc758\ubbf8\uac00 \uba85\ubc31\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud56d\uc0c1 \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4","\uace0\uac1d\uc774 \uc0ac\uc5c5\uc790\ubcf4\ub2e4 \uc6b0\uc6d4\ud55c \uc9c0\uc704\uc5d0 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uacc4\uc57d\uae08\uc561\uc774 \uc77c\uc815 \uaddc\ubaa8 \uc774\uc0c1\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 \ubcc4\ub3c4\uc758 \uc804\uc81c \uc5c6\uc774 \ubaa8\ub4e0 \uc57d\uad00 \ubd84\uc7c1\uc5d0 \uc790\ub3d9 \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.RP=s([u.Eq],t.s)
B.a1Y=s(["\uc791\uc131\uc790\ubd88\uc774\uc775 \uc6d0\uce59\uc758 \uc801\uc6a9\uc804\uc81c"],t.s)
B.apn=new A.b("gen_ai_contra_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uae30 \uc704\ud55c \uc804\uc81c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.II,0,'\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 \uc5b4\ub514\uae4c\uc9c0\ub098 "\ubcf4\ucda9\uc801" \ud574\uc11d\uc6d0\uce59\uc73c\ub85c, \ubb38\uc5b8\xb7\ubaa9\uc801\xb7\uccb4\uacc4 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud55c \ud1b5\uc0c1\uc801\uc778 \ud574\uc11d\ubc29\ubc95\uc744 \ub2e4 \ub3d9\uc6d0\ud574\ub3c4 \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \uba85\ubc31\ud788 \ud655\uc815\ub418\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uc5d0 \ube44\ub85c\uc18c \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \ud1b5\uc0c1\uc758 \ud574\uc11d\ubc29\ubc95\uc73c\ub85c \uba85\ubc31\ud788 \ud655\uc815\ub41c\ub2e4\uba74 \uc774 \uc6d0\uce59\uc774 \uac1c\uc785\ud560 \uc5ec\uc9c0\ub294 \uc5c6\ub2e4.',B.RP,B.a1Y,null)
B.Qf=s([u.c6,"\uace0\uac1d\uc774 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\ubcf4\ub2e4 \ubc95\ub960\uc9c0\uc2dd\uc774 \ubd80\uc871\ud558\uae30 \ub54c\ubb38\uc5d0 \ubb34\uc870\uac74 \uace0\uac1d\uc774 \uc774\uae34\ub2e4\ub294 \ucde8\uc9c0\uc774\ub2e4","\uc774 \uc6d0\uce59\uc740 \uc0ac\uc5c5\uc790\uc758 \uc774\uc775\uc744 \uc6b0\uc120 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc774 \uc6d0\uce59\uc740 \ubc95\uc6d0\uc758 \uc5c5\ubb34 \ubd80\ub2f4\uc744 \uc904\uc774\uae30 \uc704\ud55c \uc784\uc758\uc801 \uad00\ud589\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uc774 \uc6d0\uce59\uc740 \uad6d\uc81c\uc870\uc57d\uc5d0 \ub530\ub77c \uac15\uc81c\ub41c \uac83\uc77c \ubfd0 \uc815\ucc45\uc801 \uadfc\uac70\uac00 \uc5c6\ub2e4"],t.s)
B.aiq=s([u.c6],t.s)
B.a0j=s(["\uc791\uc131\uc790\ubd88\uc774\uc775 \uc6d0\uce59\uc758 \uadfc\uac70"],t.s)
B.asB=new A.b("gen_ai_contra_3","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc758 \uc815\ucc45\uc801 \uadfc\uac70\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Qf,0,"\uc57d\uad00\uc740 \uc0ac\uc5c5\uc790\uac00 \uc77c\ubc29\uc801\uc73c\ub85c \ub9c8\ub828\ud558\uc5ec \uace0\uac1d\uc5d0\uac8c \uc81c\uc2dc\ud558\ub294 \uac83\uc774\ubbc0\ub85c, \uadf8 \ubb38\uc5b8\uc774 \ubd88\uba85\ud655\ud558\uac8c \uc791\uc131\ub41c \ub370 \ub530\ub978 \uc704\ud5d8\uacfc \ubd88\uc774\uc775\uc740 \uc774\ub97c \uc791\uc131\ud55c \uc0ac\uc5c5\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uac83\uc774 \ud615\ud3c9\uc5d0 \ubd80\ud569\ud55c\ub2e4\ub294 \uc815\ucc45\uc801 \uace0\ub824\uac00 \uc791\uc131\uc790\ubd88\uc774\uc775 \uc6d0\uce59\uc758 \uadfc\uac70\uc774\ub2e4.",B.aiq,B.a0j,null)
B.aaI=s([u.zA,"\ubcf4\ud5d8\uc57d\uad00\uc740 \uc560\ucd08\uc5d0 \uc57d\uad00\ubc95\uc758 \uc801\uc6a9\ub300\uc0c1\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4","\ubcf4\ud5d8\uc57d\uad00\uc740 \ud56d\uc0c1 \uba85\ud655\ud558\uac8c \uc791\uc131\ub418\uc5b4 \uc774 \uc6d0\uce59\uc774 \uc801\uc6a9\ub420 \uc77c\uc774 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4","\ubcf4\ud5d8\uacc4\uc57d\uc790\ub294 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\uc758 \uc9c0\uc704\uc5d0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4","\ubcf4\ud5d8\uc57d\uad00\uc5d0\ub294 \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \ubc95\ub960\uc0c1 \uba85\uc2dc\uc801\uc73c\ub85c \ubc30\uc81c\ub418\uc5b4 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.akw=s([u.zA],t.s)
B.a_D=s(["\uc791\uc131\uc790\ubd88\uc774\uc775 \uc6d0\uce59\uc758 \uc2e4\ubb34\uc0c1 \uc801\uc6a9\ub840"],t.s)
B.atn=new A.b("gen_ai_contra_4","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\ubcf4\ud5d8\uc57d\uad00\uacfc \uac19\uc774 \uc804\ubb38\uc801\uc774\uace0 \ubcf5\uc7a1\ud55c \uc57d\uad00\uc5d0\uc11c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \ud2b9\ud788 \uc790\uc8fc \ubb38\uc81c\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aaI,0,"\ubcf4\ud5d8\uc57d\uad00\uc740 \ubcf4\uc7a5\ubc94\uc704\xb7\uba74\ucc45\uc0ac\uc720 \ub4f1\uc744 \uc815\ud558\ub294 \uc804\ubb38\uc801\uc774\uace0 \ubcf5\uc7a1\ud55c \uc870\ud56d\uc774 \ub9ce\uc544, \ubb38\uc5b8\uc758 \ub2e4\uc758\uc801 \ud574\uc11d \uac00\ub2a5\uc131\uc774 \uc0c1\ub300\uc801\uc73c\ub85c \ud06c\uac8c \ub098\ud0c0\ub098\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4. \uc774 \ub54c\ubb38\uc5d0 \uc2e4\ubb34\uc0c1 \ubcf4\ud5d8\uc57d\uad00 \uad00\ub828 \ubd84\uc7c1\uc5d0\uc11c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc790\uc8fc \ubb38\uc81c\ub418\uace0 \ud65c\uc6a9\ub41c\ub2e4.",B.akw,B.a_D,null)
B.IV=s(['\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\ufffd\uce59\uc740 "\ud574\uc11d"\uc758 \ubb38\uc81c\uc774\uace0, \ubb34\ud6a8 \ubc95\ub9ac\ub294 \ud574\uc11d\uc744 \uac70\uccd0 \ud655\uc815\ub41c \uc870\ud56d "\ub0b4\uc6a9"\uc758 \ud6a8\ub825 \ubb38\uc81c\ub85c \uc11c\ub85c \ub2e8\uacc4\uac00 \ub2e4\ub974\ub2e4',"\ub450 \ubc95\ub9ac\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uc5ec \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uba74 \uadf8 \uc870\ud56d\uc740 \ud56d\uc0c1 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubb34\ud6a8 \ubc95\ub9ac\uac00 \uc801\uc6a9\ub418\uba74 \ud574\uc11d\uc758 \ubb38\uc81c\ub294 \uc544\uc608 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\ub450 \ubc95\ub9ac\ub294 \uc11c\ub85c \uc591\ub9bd\ud560 \uc218 \uc5c6\ub294 \ubaa8\uc21c \uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.a6Z=s(['\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 "\ud574\uc11d"\uc758 \ubb38\uc81c\uc774\uace0, \ubb34\ud6a8 \ubc95\ub9ac\ub294 \ud574\uc11d\uc744 \uac70\uccd0 \ud655\uc815\ub41c \uc870\ud56d "\ub0b4\uc6a9"\uc758 \ud6a8\ub825 \ubb38\uc81c\ub85c \uc11c\ub85c \ub2e8\uacc4\uac00 \ub2e4\ub974\ub2e4'],t.s)
B.NU=s(["\ud574\uc11d\uacfc \ubb34\ud6a8\ud310\ub2e8\uc758 \ub2e8\uacc4 \uad6c\ubd84"],t.s)
B.axd=new A.b("gen_ai_contra_5","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59(\uc81c5\uc870 \uc81c2\ud56d)","\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uacfc \ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d \ubb34\ud6a8 \ubc95\ub9ac\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.IV,0,'\uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc740 \uc870\ud56d\uc758 \ub73b\uc774 \uba85\ubc31\ud558\uc9c0 \uc54a\uc744 \ub54c "\uc5b4\ub5bb\uac8c \ud574\uc11d\ud560 \uac83\uc778\uac00"\uc758 \ubb38\uc81c\uc778 \ubc18\uba74, \ubb34\ud6a8 \ubc95\ub9ac(\uc81c6\uc870~\uc81c14\uc870)\ub294 \ud574\uc11d\uc744 \ud1b5\ud574 \ud655\uc815\ub41c \uc870\ud56d\uc758 "\ub0b4\uc6a9" \uc790\uccb4\uac00 \ubd88\uacf5\uc815\ud558\uc5ec \ud6a8\ub825\uc744 \uc778\uc815\ud560 \uc218 \uc5c6\ub294\uc9c0\uc758 \ubb38\uc81c\uc774\ub2e4. \ub450 \ubc95\ub9ac\ub294 \uc21c\ucc28\uc801\uc73c\ub85c \uac80\ud1a0\ub420 \uc218 \uc788\ub294 \uc11c\ub85c \ub2e4\ub978 \ub2e8\uacc4\uc758 \uc7c1\uc810\uc774\ub2e4.',B.a6Z,B.NU,null)
B.Ie=s([u.q2,"\uc774\ub7ec\ud55c \uacb0\uacfc\ub294 \ud56d\uc0c1 \ubd80\ub2f9\ud558\ubbc0\ub85c \ubc95\uc6d0\uc774 \ubc18\ub4dc\uc2dc \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \uc7ac\ud574\uc11d\ud574\uc57c \ud55c\ub2e4","\uc774 \uacbd\uc6b0 \uacc4\uc57d \uc790\uccb4\uac00 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uace0\uac1d\uc774 \uc624\ud788\ub824 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4","\uc774 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c \uacb0\uacfc\ub294 \ud56d\uc0c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
