B.ayS=new A.b("gen_ai_case_1","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840",'\ubcf4\ud5d8\uc57d\uad00\uc0c1 \uba74\ucc45\uc870\ud56d\uc758 \ubb38\uc5b8\uc774 "\ucc9c\uc7ac\uc9c0\ubcc0\uc73c\ub85c \uc778\ud55c \uc190\ud574"\ub77c\uace0\ub9cc \ub418\uc5b4 \uc788\uc5b4 \ud2b9\uc815 \uc790\uc5f0\uc7ac\ud574\uac00 \uc774\uc5d0 \ud3ec\ud568\ub418\ub294\uc9c0 \ub2e4\ud22c\uc5b4\uc9c0\ub294 \uacbd\uc6b0, \ud574\uc11d \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.UV,0,"\uc57d\uad00 \uc870\ud56d\uc758 \ud574\uc11d\uc740 \uc6b0\uc120 \ubb38\uc5b8\xb7\ubaa9\uc801\xb7\uccb4\uacc4 \ub4f1\uc744 \uace0\ub824\ud55c \ud1b5\uc0c1\uc758 \ud574\uc11d\ubc29\ubc95\uacfc \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc5d0 \ub530\ub77c \uacf5\uc815\ud558\uace0 \ud1b5\uc77c\uc801\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\uba70, \uadf8\ub7fc\uc5d0\ub3c4 \uc870\ud56d\uc758 \uc758\ubbf8\uac00 \uba85\ubc31\ud788 \ud655\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4\uba74 \ubcf4\ucda9\uc801\uc73c\ub85c \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc5d0 \ub530\ub77c \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ud574\uc11d\ud558\ub294 \uc21c\uc11c\ub85c \uc811\uadfc\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.",B.WL,B.Mj,null)
B.a4G=s([u.cN,"\uac01 \uace0\uac1d\uc774 \uc6d0\ud558\ub294 \ud574\uc11d\uc744 \uadf8\ub300\ub85c \uc778\uc815\ud574\uc57c \ud55c\ub2e4","\uba3c\uc800 \uc18c\ub97c \uc81c\uae30\ud55c \uace0\uac1d\uc758 \ud574\uc11d\uc774 \ud56d\uc0c1 \uc6b0\uc120\ud55c\ub2e4","\uc0ac\uc5c5\uc790\uac00 \uc81c\uc2dc\ud558\ub294 \ud574\uc11d\uc774 \ud56d\uc0c1 \ucd5c\uc885\uc801\uc73c\ub85c \uc778\uc815\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uc57d\uad00 \uc790\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \uc804\ubd80 \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.Vd=s([u.cN],t.s)
B.a9L=s(["\ubcf5\uc218 \uace0\uac1d \uac04 \ud574\uc11d \ub2e4\ud23c"],t.s)
B.arn=new A.b("gen_ai_case_2","economic_law","\uc57d\uad00 \ud574\uc11d\xb7\ucd1d\uce59","\uc57d\uad00 \ud574\uc11d \uc885\ud569\xb7\uc0ac\ub840","\ub3d9\uc77c\ud55c \uc774\ub3d9\ud1b5\uc2e0 \uc11c\ube44\uc2a4 \uc57d\uad00 \uc870\ud56d\uc5d0 \ub300\ud574 \uc11c\ub85c \ub2e4\ub978 \uace0\uac1d\uc774 \uc0c1\ubc18\ub41c \ud574\uc11d\uc744 \uc8fc\uc7a5\ud558\ub294 \uacbd\uc6b0, \uc57d\uad00 \ud574\uc11d\uc758 \uc811\uadfc \ubc29\ubc95\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a4G,0,"\uc57d\uad00\uc740 \ub2e4\uc218\uc758 \uace0\uac1d\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub418\ub294 \uac83\uc744 \uc804\uc81c\ub85c \ud558\ubbc0\ub85c, \ud2b9\uc815 \uace0\uac1d\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uc774\ub098 \uc120\ud638\uac00 \uc544\ub2c8\ub77c \ud3c9\uade0\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 \uace0\uac1d\uc744 \uae30\uc900\uc73c\ub85c \ud55c \uac1d\uad00\uc801\xb7\ud1b5\uc77c\uc801 \ud574\uc11d\uc744 \uc2dc\ub3c4\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \uc57d\uad00 \ud574\uc11d\uc5d0\uc11c \uc77c\uad00\ub418\uac8c \uac15\uc870\ub418\ub294 \uc811\uadfc\ubc29\ubc95\uc774\ub2e4.",B.Vd,B.a9L,null)
B.MC=s([u.jn,"\ubb38\uc5b8\uc774 \uba85\ud655\ud558\uba74 \uadf8 \uacb0\uacfc\uac00 \uc544\ubb34\ub9ac \uac00\ud639\ud574\ub3c4 \uc5b4\ub5a0\ud55c \ud1b5\uc81c\ub3c4 \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\ubb38\uc5b8\uc774 \uba85\ud655\ud558\uba74 \ud56d\uc0c1 \uc791\uc131\uc790\ubd88\uc774\uc775\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uc5b4 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud558\uac8c \ub4a4\uc9d1\ud78c\ub2e4","\uc774 \uacbd\uc6b0 \uacc4\uc57d \uc790\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \ud574\uc81c\ub41c\ub2e4","\uc774 \uacbd\uc6b0 \uace0\uac1d\uc740 \uc5b4\ub5a0\ud55c \uad6c\uc81c\uc218\ub2e8\ub3c4 \uac00\uc9c8 \uc218 \uc5c6\ub2e4"],t.s)
B.a3T=s([u.jn],t.s)
