B.aCe=new A.b("gen_std_effect_6","economic_law","\ud45c\uc900\uc57d\uad00","\ud45c\uc900\uc57d\uad00 \ud45c\uc9c0 \uc0ac\uc6a9\uc758 \ud6a8\uacfc","\ud45c\uc900\uc57d\uad00 \uc81c\ub3c4\uc640 \uac00\ub9f9\uc0ac\uc5c5\ubc95\uc0c1 \ud45c\uc900\uac00\ub9f9\uacc4\uc57d\uc11c \uc81c\ub3c4\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Wi,0,"\uc57d\uad00\ubc95\uc0c1 \ud45c\uc900\uc57d\uad00 \uc81c\ub3c4\uc640 \uac00\ub9f9\uc0ac\uc5c5\ubc95\uc0c1 \ud45c\uc900\uac00\ub9f9\uacc4\uc57d\uc11c \uc81c\ub3c4\ub294 \uac01\uac01 \uadfc\uac70 \ubc95\ub960\uc740 \ub2e4\ub974\uc9c0\ub9cc, \ud45c\uc900\uc774 \ub418\ub294 \uacc4\uc57d(\uc57d\uad00) \ub0b4\uc6a9\uc744 \ub9c8\ub828\xb7\uc81c\uc2dc\ud558\uc5ec \uac70\ub798\uc758 \uacf5\uc815\uc131\uacfc \uc608\uce21\uac00\ub2a5\uc131\uc744 \ub192\uc774\ub824\ub294 \ucde8\uc9c0\ub97c \uacf5\uc720\ud558\ub294 \uc720\uc0ac\ud55c \uc131\uaca9\uc758 \uc81c\ub3c4\ub85c \uc774\ud574\ud560 \uc218 \uc788\ub2e4.",B.a_Q,B.a5n,null)
B.a1_=s([u.j_,"\ud574\ub2f9 \uc5c5\uc885\uc758 \uc0ac\uc5c5\uc790 \uc218\ub97c \uac15\uc81c\ub85c \uc904\uc774\uae30 \uc704\ud568\uc774\ub2e4","\ud574\ub2f9 \uc5c5\uc885\uc758 \uac00\uaca9\uc744 \uc815\ubd80\uac00 \uc9c1\uc811 \ud1b5\uc81c\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ud574\ub2f9 \uc5c5\uc885\uc5d0\uc11c\ub9cc \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub97c \ud5c8\uc6a9\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ud574\ub2f9 \uc5c5\uc885\uc758 \uc138\uae08\uc744 \uac10\uba74\ud558\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
