B.asr=new A.b("gen_iv_obstruct_5","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc870\uc0ac\ubc29\ud574 \ud589\uc704\uc5d0 \ub300\ud55c \uc81c\uc7ac\uac00 \ud544\uc694\ud55c \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.TP,0,"\uc870\uc0ac\uc5d0 \ub300\ud55c \ud611\uc870\uac00 \ud655\ubcf4\ub418\uc9c0 \uc54a\uc73c\uba74 \uc2e4\ud6a8\uc801\uc778 \ubc95 \uc9d1\ud589\uc774 \uc5b4\ub824\uc6cc\uc838 \uacf5\uc815\uac70\ub798\ubc95 \uc804\uccb4\uc758 \uaddc\ubc94\ub825\uc774 \uc57d\ud654\ub420 \uc218 \uc788\ub2e4. \uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac\ub294 \uc774\ub7ec\ud55c \uc0c1\ud669\uc744 \ubc29\uc9c0\ud558\uace0 \uc2e4\ud6a8\uc801\uc778 \uc870\uc0ac\uc640 \ubc95 \uc9d1\ud589\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud55c \uc815\ucc45\uc801 \uc7a5\uce58\uc774\ub2e4.",B.Zu,B.S2,null)
B.O9=s([u.v8,"\uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc9c0\uc2dc\ub294 \uc870\uc0ac\ubc29\ud574\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \ubb38\uc81c\uc774\ub2e4","\uad6c\uc131\uc0ac\uc5c5\uc790\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc758 \uc9c0\uc2dc\ub97c \ub530\ub790\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubaa8\ub4e0 \ucc45\uc784\uc5d0\uc11c \uba74\uc81c\ub41c\ub2e4","\uc0ac\uc5c5\uc790\ub2e8\uccb4\ub294 \uc870\uc0ac \uad00\ub828 \ubb38\uc81c\uc5d0\uc11c \uc5b4\ub5a0\ud55c \ucc45\uc784\ub3c4 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uacbd\uc6b0 \uc870\uc0ac \uc790\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \uc885\uacb0\ub41c\ub2e4"],t.s)
