B.as_=new A.b("gen_clause_review_request_5","economic_law","\uc57d\uad00 \uc2ec\uc0ac\xb7\uc2dc\uc815\uc808\ucc28","\uc57d\uad00 \uc2ec\uc0ac\uccad\uad6c\xb7\uc9c1\uad8c\uc2ec\uc0ac","\ub2e4\ub978 \ubc95\ub960\uc5d0 \ub530\ub77c \ud589\uc815\uad00\uccad\uc758 \uc778\uac00\ub97c \ubc1b\uc740 \uc57d\uad00\uc5d0 \ub300\ud55c \uc2ec\uc0ac\uccad\uad6c\uc758 \ucde8\uae09\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a6z,0,"\ub2e4\ub978 \ubc95\ub960\uc5d0 \ub530\ub77c \ud2b9\uc815 \ud589\uc815\uae30\uad00\uc758 \uc778\uac00\ub97c \ubc1b\uc544\uc57c \ud558\ub294 \uc57d\uad00\uc758 \uacbd\uc6b0, \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2ec\uc0ac\uc640 \uc18c\uad00 \ud589\uc815\uae30\uad00\uc758 \uc778\uac00 \uad8c\ud55c\uc774 \uc11c\ub85c \uc5b4\ub5bb\uac8c \uc870\uc728\ub418\ub294\uc9c0(\uad00\ud560\xb7\ud611\uc870 \uad00\uacc4)\uac00 \uc2e4\ubb34\uc0c1 \ubb38\uc81c\ub420 \uc218 \uc788\ub294 \uc9c0\uc810\uc73c\ub85c \ub17c\uc758\ub41c\ub2e4.",B.aj4,B.Wy,null)
B.He=s([u.yN,"\uc57d\uad00 \uc2ec\uc0ac \uc81c\ub3c4\ub294 \uacc4\uc57d \uc790\uc720\uc758 \uc6d0\uce59\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4","\uc57d\uad00 \uc2ec\uc0ac \uc81c\ub3c4\ub294 \uacc4\uc57d \uc790\uc720\uc758 \uc6d0\uce59\uc744 \uc644\uc804\ud788 \ubd80\uc815\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc57d\uad00 \uc2ec\uc0ac\ub294 \uc0ac\uc5c5\uc790\uc758 \uacc4\uc57d \uc790\uc720\ub9cc\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc57d\uad00 \uc2ec\uc0ac\ub294 \uc18c\ube44\uc790\uc758 \uacc4\uc57d \uc790\uc720\ub97c \uc81c\ud55c\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4"],t.s)
