B.aAY=new A.b("gen_pc_proc_1","economic_law","\uacfc\uc9d5\uae08","\ubd80\uacfc\uc808\ucc28\xb7\uac10\uba74","\uacfc\uc9d5\uae08 \ubd80\uacfc\uc5d0 \uc55e\uc11c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uac70\uce58\ub294 \uc808\ucc28\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a8P,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc870\uc0ac \uacb0\uacfc\ub97c \ubc14\ud0d5\uc73c\ub85c \uc2ec\uc758 \ub4f1\uc758 \uc808\ucc28\ub97c \uac70\uce58\uba70, \uc774 \uacfc\uc815\uc5d0\uc11c \uc704\ubc18\ud610\uc758\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc758\uacac\uc9c4\uc220 \uae30\ud68c\ub97c \ubd80\uc5ec\ud55c \ud6c4 \uc804\uc6d0\ud68c\uc758\ub098 \uc18c\ud68c\uc758\uc758 \uc758\uacb0\uc744 \ud1b5\ud574 \uc2dc\uc815\uc870\uce58\xb7\uacfc\uc9d5\uae08 \ubd80\uacfc \uc5ec\ubd80\uc640 \uae08\uc561\uc744 \uacb0\uc815\ud55c\ub2e4.",B.aaM,B.a2T,null)
B.a3p=s(["\uc77c\uc815\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0 \ub0a9\ubd80\uae30\ud55c\uc758 \uc5f0\uc7a5\uc774\ub098 \ubd84\ud560\ub0a9\ubd80\ub97c \uc2e0\uccad\ud560 \uc218 \uc788\ub2e4","\uacfc\uc9d5\uae08\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubd84\ud560\ub0a9\ubd80\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub0a9\ubd80\uae30\ud55c \uc5f0\uc7a5 \uc2e0\uccad\uc5d0\ub294 \uc544\ubb34\ub7f0 \uae30\ud55c \uc81c\ud55c\uc774 \uc5c6\ub2e4","\ubd84\ud560\ub0a9\ubd80\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \ud5c8\uc6a9\ub41c\ub2e4","\ub0a9\ubd80\uae30\ud55c \uc5f0\uc7a5\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2b9\uc778 \uc5c6\uc774 \uc0ac\uc5c5\uc790\uac00 \uc784\uc758\ub85c \uacb0\uc815\ud560 \uc218 \uc788\ub2e4"],t.s)
