B.aux=new A.b("gen_appeal_lawsuit_6","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\ud589\uc815\uc18c\uc1a1 \ub4f1 \uc0ac\ubc95\uc801 \ubd88\ubcf5\uc808\ucc28","\uace0\ub4f1\ubc95\uc6d0\uc758 \ud310\uacb0\uc5d0 \ub300\ud574 \ub2e4\uc2dc \ubd88\ubcf5\ud558\uace0\uc790 \ud558\ub294 \uacbd\uc6b0 \ucde8\ud560 \uc218 \uc788\ub294 \uc808\ucc28\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.XY,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ucc98\ubd84\uc5d0 \ub300\ud55c \ucde8\uc18c\uc18c\uc1a1\uc744 \uc2ec\ub9ac\ud55c \uace0\ub4f1\ubc95\uc6d0\uc758 \ud310\uacb0\uc5d0 \ubd88\ubcf5\ud558\ub294 \ub2f9\uc0ac\uc790\ub294, \ud1b5\uc0c1\uc801\uc778 \uc2ec\uae09 \uad6c\uc870\uc5d0 \ub530\ub77c \ub300\ubc95\uc6d0\uc5d0 \uc0c1\uace0\ub97c \uc81c\uae30\ud558\uc5ec \ubc95\ub960\uc2ec \ucc28\uc6d0\uc758 \uc7ac\uc2ec\uc0ac\ub97c \ubc1b\uc744 \uc218 \uc788\ub2e4.",B.ajp,B.PB,null)
