B.av_=new A.b("gen_appeal_exam_1","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uac00\ub9f9\uac70\ub798\uc0ac \uc2dc\ud5d8\uc5d0\uc11c \uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\uac00 \uc790\uc8fc \ub2e4\ub8e8\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.VI,0,"\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\ub294 \uc774\uc758\uc2e0\uccad\uc774 \ud589\uc815\uc18c\uc1a1\uc758 \ud544\uc218\uc801 \uc804\uce58\uc808\ucc28\uac00 \uc544\ub2c8\ub77c\ub294 \uc810, \ucde8\uc18c\uc18c\uc1a1\uc758 \uc804\uc18d\uad00\ud560\uc774 \uc11c\uc6b8\uace0\ub4f1\ubc95\uc6d0\uc774\ub77c\ub294 \uc810\uacfc \uc81c\uc18c\uae30\uac04\uc774\ub77c\ub294 \ud575\uc2ec \ucd95\uc744 \uc911\uc2ec\uc73c\ub85c \ucd9c\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.",B.Vt,B.bc,null)
B.afl=s(["\uc774\uc758\uc2e0\uccad\uc744 \ubc18\ub4dc\uc2dc \uac70\uccd0\uc57c\ub9cc \ud589\uc815\uc18c\uc1a1\uc744 \uc81c\uae30\ud560 \uc218 \uc788\ub2e4\uace0 \uc11c\uc220\ud558\ub294 \uc120\ud0dd\uc9c0","\uac00\ub9f9\uacc4\uc57d\uc11c\uc758 \ud3f0\ud2b8 \ud06c\uae30\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccad\uc0ac\uc758 \uce35\uc218\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc704\uc6d0\uc7a5\uc758 \uac1c\uc778 \ucde8\ubbf8\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc2ec\uc0ac\uccad\uad6c \uc811\uc218 \ucc3d\uad6c\uc758 \uc8fc\uc18c\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0"],t.s)
B.UG=s(["\uc774\uc758\uc2e0\uccad\uc744 \ubc18\ub4dc\uc2dc \uac70\uccd0\uc57c\ub9cc \ud589\uc815\uc18c\uc1a1\uc744 \uc81c\uae30\ud560 \uc218 \uc788\ub2e4\uace0 \uc11c\uc220\ud558\ub294 \uc120\ud0dd\uc9c0"],t.s)
B.ax3=new A.b("gen_appeal_exam_2","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \uad00\ub828 \ubb38\uc81c\uc5d0\uc11c \uc790\uc8fc \ucd9c\uc81c\ub418\ub294 \ud568\uc815 \uc720\ud615\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.afl,0,"\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \ubb38\uc81c\uc5d0\uc11c\ub294 \uc774\uc758\uc2e0\uccad\uc744 \ud544\uc218\uc801 \uc804\uce58\uc808\ucc28\ub85c \uc11c\uc220\ud558\uc5ec \uc774\ub97c \uac70\uce58\uc9c0 \uc54a\uc73c\uba74 \ud589\uc815\uc18c\uc1a1\uc744 \uc81c\uae30\ud560 \uc218 \uc5c6\ub2e4\uace0 \uc624\ub3c4\ud558\ub294 \uc120\ud0dd\uc9c0\uac00 \ud568\uc815\uc73c\ub85c \uc790\uc8fc \ucd9c\uc81c\ub418\ubbc0\ub85c, \uc774\uc758\uc2e0\uccad\uc774 \uc784\uc758\uc801 \uc808\ucc28\ub77c\ub294 \uc810\uc744 \uc815\ud655\ud788 \uad6c\ubcc4\ud574 \ub450\uc5b4\uc57c \ud55c\ub2e4.",B.UG,B.cx,null)
B.LE=s([u.jK,"\ubd88\ubcf5\uc808\ucc28\ub294 \uc544\ubb34 \ub54c\ub098 \uc81c\uae30\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\uc774\uc758\uc2e0\uccad\uacfc \ud589\uc815\uc18c\uc1a1\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc808\ucc28\ub77c\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ubd88\ubcf5\uc808\ucc28\ub294 \uc790\ubb38\ud560 \ud544\uc694\uac00 \uc5c6\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4","\ucc98\ubd84\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ubd88\ubcf5\uc808\ucc28\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc548\ub0b4\ud558\uba74 \ub41c\ub2e4"],t.s)
