B.aiM=s(["\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc640 \uc870\uc0ac\uc808\ucc28\uc758 \uad00\uacc4"],t.s)
B.az0=new A.b("gen_appeal_exam_5","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc640 \uc870\uc0ac\uc808\ucc28\xb7\ucc98\ubd84\uc2dc\ud6a8 \ud30c\ud2b8\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a6o,0,"\uc870\uc0ac\uc808\ucc28 \ud30c\ud2b8\uac00 \uc2e0\uace0\xb7\uc778\uc9c0\ubd80\ud130 \uc2ec\uc758\xb7\ucc98\ubd84\uc5d0 \uc774\ub974\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\uc744 \ub2e4\ub8ec\ub2e4\uba74, \uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28 \ud30c\ud2b8\ub294 \uadf8 \ucc98\ubd84\uc774 \ub0b4\ub824\uc9c4 \uc774\ud6c4 \ucc98\ubd84\uc758 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ub2e4\ud22c\ub294 \uad8c\ub9ac\uad6c\uc81c \uc808\ucc28\ub97c \ub2e4\ub8ec\ub2e4\ub294 \uc810\uc5d0\uc11c, \ub450 \ud30c\ud2b8\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc0ac\uac74 \ucc98\ub9ac\uc758 \uc804\uccb4 \ud750\ub984\uc5d0\uc11c \uc55e\ub4a4\ub97c \uc774\ub8e8\ub294 \ubcf4\uc644\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.a18,B.aiM,null)
B.a4M=s([u.B0,"\uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \ucc98\ubd84\uc744 \ub2e4\ud22c\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc788\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc18c\ube44\uc790\ub2e8\uccb4\uc5d0\uac8c \uc788\ub2e4","\ucde8\uc18c\uc18c\uc1a1\uc5d0\ub294 \uc99d\uba85\ucc45\uc784\uc774\ub77c\ub294 \uac1c\ub150 \uc790\uccb4\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \uc624\uc9c1 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uc73c\ub85c\ub9cc \uacb0\uc815\ub41c\ub2e4"],t.s)
B.RY=s([u.B0],t.s)
B.Iz=s(["\ucde8\uc18c\uc18c\uc1a1\uc758 \uc99d\uba85\ucc45\uc784"],t.s)
B.aug=new A.b("gen_appeal_exam_6","economic_law","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uc774\uc758\uc2e0\uccad\xb7\ubd88\ubcf5\uc808\ucc28\uc5d0\uc11c \uc99d\uba85\ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a4M,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \ucc98\ubd84\uc5d0 \ub300\ud55c \ucde8\uc18c\uc18c\uc1a1\uc5d0\uc11c, \ucc98\ubd84\uc758 \uc801\ubc95\uc131(\uc704\ubc18\uc0ac\uc2e4\uc758 \uc874\uc7ac, \ucc98\ubd84\uc758 \uc815\ub2f9\uc131 \ub4f1)\uc5d0 \ub300\ud55c \uc99d\uba85\ucc45\uc784\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ucc98\ubd84\uc744 \ub0b4\ub9b0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubd80\ub2f4\ud558\ub294 \uac83\uc774 \ud589\uc815\uc18c\uc1a1\uc758 \uc77c\ubc18\uc801\uc778 \uc99d\uba85\ucc45\uc784 \ubd84\ubc30 \uc6d0\uce59\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.RY,B.Iz,null)
