B.Ky=s([u.n,"\uac00\uaca9\uc744 \uc5bc\ub9c8\ub098 \ub0ae\ucdc4\ub294\uc9c0 \uadf8 \uc808\ub300\uc801\uc778 \uae08\uc561 \ud06c\uae30","\ud560\uc778 \ud589\uc0ac\uc758 \uba85\uce6d\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc5ec\ubd80","\uac00\uaca9 \uc778\ud558\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc694\uc77c","\uc0c1\ud488\uc758 \uc0c9\uae54"],t.s)
