B.Ob=s([u.mv,"\uac70\ub798\uc0c1\ub300\ubc29\uc774 \uc18c\ube44\uc790\uc778\uc9c0 \uc0ac\uc5c5\uc790\uc778\uc9c0 \uc5ec\ubd80","\uc0c1\ud488\uc758 \uc885\ub958\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc5ec\ubd80","\uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc9c0\uc5ed\uc774 \uc5b4\ub514\uc778\uc9c0 \uc5ec\ubd80","\uc0ac\uc5c5\uc790\uc758 \uc124\ub9bd\uc5f0\ub3c4"],t.s)
