B.au5=new A.b("gen_interfere_exam_1","economic_law","\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574","\uc2dc\ud5d8 \ud3ec\uc778\ud2b8\xb7\uc2e4\ubb34 \uc801\uc6a9","\uac00\ub9f9\uac70\ub798\uc0ac \uc2dc\ud5d8\uc5d0\uc11c \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574 \uad00\ub828 \ubb38\uc81c\uac00 \uc790\uc8fc \ub2e4\ub8e8\ub294 \ud575\uc2ec \ud3ec\uc778\ud2b8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a26,0,'\uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574 \uad00\ub828 \ubb38\uc81c\ub294 \uae30\uc220\uc758 \ubd80\ub2f9\uc774\uc6a9, \uc778\ub825\uc758 \ubd80\ub2f9\uc720\uc778\xb7\ucc44\uc6a9, \uac70\ub798\ucc98 \uc774\uc804\ubc29\ud574\ub77c\ub294 \ud558\uc704 \uc720\ud615\uc758 \uad6c\ubcc4\uacfc, "\uc0ac\uc5c5\ud65c\ub3d9\uc744 \uc2ec\ud788 \uace4\ub780\ud558\uac8c \ud55c\ub2e4"\ub294 \ubd80\ub2f9\uc131 \uc694\uac74\uc758 \uc758\ubbf8\ub97c \uc911\uc2ec\uc73c\ub85c \ucd9c\uc81c\ub418\ub294 \uacbd\ud5a5\uc774 \uc788\ub2e4.',B.akW,B.bc,null)
B.a8A=s([u.Cn,"\uac00\ub9f9\uacc4\uc57d\uc11c\uc758 \ud3f0\ud2b8 \ud06c\uae30\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccad\uc0ac\uc758 \uce35\uc218\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc704\uc6d0\uc7a5\uc758 \uac1c\uc778 \ucde8\ubbf8\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0","\uc2ec\uc0ac\uccad\uad6c \uc811\uc218 \ucc3d\uad6c\uc758 \uc8fc\uc18c\ub97c \ubb3b\ub294 \uc120\ud0dd\uc9c0"],t.s)
