B.adq=s([u.Bv,"\uc0ac\uc5c5\uc790\ub4e4\uc774 \ub2f4\ud569\ud558\uc5ec \uac00\uaca9\uc744 \uc784\uc758\ub85c \ud1b5\uc77c\ud558\ub294 \uac83","\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc870\uac74\uc744 \uc77c\ubc29\uc801\uc73c\ub85c \uac15\uc694\ud558\ub294 \uac83","\uacbd\uc7c1\uc0ac\uc5c5\uc790\ub97c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub294 \uac83","\uc18c\ube44\uc790\uc758 \uc120\ud0dd\uad8c\uc744 \uc644\uc804\ud788 \uc81c\uac70\ud558\ub294 \uac83"],t.s)
