B.aAR=new A.b("gen_collusion_type_limit_4","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \uc0dd\uc0b0\xb7\uac70\ub798 \uc2dc\uc5d0 \uadf8 \uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \uc885\ub958\xb7\uaddc\uaca9\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.aa7,0,'"\uc0c1\ud488\xb7\uc6a9\uc5ed\uc758 \uc885\ub958\xb7\uaddc\uaca9\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704"\ub294 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud569\uc758\ud558\uc5ec \uc0dd\uc0b0\xb7\ud310\ub9e4\ud558\ub294 \uc0c1\ud488\uc758 \uc885\ub958\ub098 \uaddc\uaca9\uc758 \ub2e4\uc591\uc131\uc744 \uc778\uc704\uc801\uc73c\ub85c \uc81c\ud55c\ud568\uc73c\ub85c\uc368, \uc18c\ube44\uc790\uc758 \uc120\ud0dd\uad8c\uc744 \ucd95\uc18c\uc2dc\ud0a4\uace0 \uad00\ub828 \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.aae,B.ai5,null)
B.a5W=s([u.uv,"\uc0ac\uc5c5\uc790\ub4e4\uc774 \uc815\ub2f9\ud55c \uc808\ucc28\ub97c \uac70\uccd0 \ud569\uc791\ud68c\uc0ac\ub97c \uc124\ub9bd\ud558\uace0 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uae30\uc5c5\uacb0\ud569 \uc2ec\uc0ac\ub97c \ubc1b\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc790\ud68c\uc0ac\ub97c \uc124\ub9bd\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\ub4e4\uc774 \ubcc4\ub3c4\uc758 \ud68c\uc0ac \uc124\ub9bd \uc5c6\uc774 \uac01\uc790 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc601\uc5c5\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \uacf5\uae30\uc5c5\uc744 \uc124\ub9bd\ud558\ub294 \ud589\uc704"],t.s)
