B.atm=new A.b("gen_collusion_type_limit_6","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615","\uc785\ucc30\ub2f4\ud569\uc774 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 \uc5b4\ub514\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a0B,0,"\uc785\ucc30\ub2f4\ud569\uc740 \ub099\ucc30\uc608\uc815\uc790\ub97c \uc0ac\uc804\uc5d0 \uc815\ud558\uace0 \ud22c\ucc30\uac00\uaca9\uc744 \ud569\uc758\ud558\ub294 \ub4f1 \uc2e4\uc9c8\uc801\uc73c\ub85c \uac00\uaca9 \uacb0\uc815, \uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \ub4f1 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\uc758 \uc5ec\ub7ec \ubc95\uc815 \uc720\ud615\uc774 \uacb0\ud569\ub418\uc5b4 \ub098\ud0c0\ub098\ub294 \ub300\ud45c\uc801\uc778 \ub2f4\ud569 \ud615\ud0dc\ub85c \uc774\ud574\ub418\uba70, \uadf8 \uad6c\uccb4\uc801 \ud569\uc758 \ub0b4\uc6a9\uc5d0 \ub530\ub77c \ud574\ub2f9\ud558\ub294 \uc720\ud615\uc774 \ubcf5\ud569\uc801\uc73c\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.IP,B.al_,null)
B.Ht=s([u.on,"\uacbd\uc7c1\uc0ac\uc5c5\uc790\uac00 \uc790\ubc1c\uc801\uc73c\ub85c \uc0ac\uc5c5\uc744 \ucd95\uc18c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc2e0\uaddc \uc0ac\uc5c5\uc5d0 \uc9c4\ucd9c\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \ud2b9\uc815 \uc0ac\uc5c5\uc790\uc758 \uc778\ud5c8\uac00\ub97c \ucde8\uc18c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc815\ub2f9\ud55c \uacbd\uc7c1\uc744 \ud1b5\ud574 \uc2dc\uc7a5\uc810\uc720\uc728\uc744 \ud655\ub300\ud558\ub294 \ud589\uc704"],t.s)
