B.apt=new A.b("gen_md_case_3","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \ubc18\ub3c4\uccb4 \uc218\uc694 \uae09\uc99d \uc0c1\ud669\uc5d0\uc11c \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0dd\uc0b0\ub7c9\uc744 \uc885\uc804 \ub300\ube44 \ud604\uc800\ud788 \uc904\uc5ec \uc2dc\uc7a5\uc5d0 \uc778\uc704\uc801\uc778 \ud488\uadc0 \ud604\uc0c1\uc744 \uc77c\uc73c\ud0a8 \uacbd\uc6b0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \ub0a8\uc6a9\ud589\uc704 \uc720\ud615\uc740?",B.I3,0,"\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc0dd\uc0b0\xb7\ucd9c\uace0\ub7c9\uc744 \ucd5c\uadfc \ucd94\uc138\ubcf4\ub2e4 \ud604\uc800\ud788 \uac10\uc18c\uc2dc\ucf1c \uc218\uae09\uc5d0 \uc778\uc704\uc801 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub294 \ucd9c\uace0\uc870\uc808\uc758 \uc804\ud615\uc801 \uc0ac\ub840\uc774\ub2e4. \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\xb7\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\xb7\uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\xb7\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \uac01\uac01 \ub2e4\ub978 \uc694\uac74\uacfc \uc8fc\uccb4\ub97c \uc804\uc81c\ub85c \ud558\ub294 \ubcc4\uac1c\uc758 \uaddc\uc81c \uc720\ud615\uc73c\ub85c, \uc774 \uc0ac\ub840\uc640\ub294 \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.",B.adL,B.a9I,null)
B.a5z=s([u.cL,"\uc2e0\uaddc \uc9c4\uc785\uc744 \ub9c9\ub294 \ud589\uc704\ub294 \uc774\uc720\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \uc704\ubc95\ud558\ub2e4","\uc548\uc804\uae30\uc900\uc744 \uc774\uc720\ub85c \ub4e0 \uacbd\uc6b0\ub294 \ud56d\uc0c1 \ud615\uc2dd\uc801 \ud56d\ubcc0\uc73c\ub85c \ucde8\uae09\ub418\uc5b4 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub85c \uc758\uc728\ud574\uc57c \ud55c\ub2e4","\uc774 \uacbd\uc6b0\ub294 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\ub85c\ub9cc \uaddc\uc728\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aaV=s([u.cL],t.s)
B.aa3=s(["\uc815\ub2f9\ud55c \uc774\uc720 \ud56d\ubcc0 \uc0ac\ub840"],t.s)
B.atJ=new A.b("gen_md_case_4","economic_law","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9","\ud310\ub840\xb7\uc0ac\ub840","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790 A\uc0ac\uac00 \uc2e0\uaddc \uc9c4\uc785\uc744 \uc2dc\ub3c4\ud558\ub294 B\uc0ac\uc5d0\uac8c \ud544\uc218\uc801\uc778 \uc720\ud1b5\ub9dd \uc811\uadfc\uc744 \uac70\uc808\ud558\uba74\uc11c, \ub3d9\uc2dc\uc5d0 \uadf8 \uac70\uc808\uc774 \uc548\uc804\uae30\uc900 \ubbf8\ub2ec\uc744 \uc774\uc720\ub85c \ud55c \ud569\ub9ac\uc801 \uc870\uce58\uc600\uc74c\uc774 \uac1d\uad00\uc801\uc73c\ub85c \uc785\uc99d\ub41c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a5z,0,'\ub0a8\uc6a9\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\ub294 \ud589\uc704\ub77c\ub3c4, \uc548\uc804\xb7\ud488\uc9c8\uad00\ub9ac \ub4f1 \uac1d\uad00\uc801\uc774\uace0 \ud569\ub9ac\uc801\uc778 "\uc815\ub2f9\ud55c \uc774\uc720"\uac00 \uc2e4\uc81c\ub85c \uc785\uc99d\ub41c\ub2e4\uba74 \uc704\ubc95\uc131\uc774 \uc870\uac01\ub418\uc5b4 \ub0a8\uc6a9\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uc774\ub7ec\ud55c \ud56d\ubcc0\uc740 \ud615\uc2dd\uc801 \uc8fc\uc7a5\ub9cc\uc73c\ub85c\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uac1d\uad00\uc801 \uadfc\uac70\uac00 \ub4b7\ubc1b\uce68\ub418\uc5b4\uc57c \ud558\uba70, \uc774 \uc0ac\ub840\ub294 \ubd80\ub2f9\uacf5\ub3d9\ud589\uc704\ub098 \uc0ac\uc5c5\uc790\ub2e8\uccb4 \uae08\uc9c0\ud589\uc704\uc640\ub294 \ubb34\uad00\ud55c \ub2e8\ub3c5\ud589\uc704 \uc0ac\uc548\uc774\ub2e4.',B.aaV,B.aa3,null)
B.TQ=s(["\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc704\ubc18","\ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\ud589\uc704"],t.s)
B.a4E=s(["\ub2e4\ub978 \uc0ac\uc5c5\uc790\uc758 \uc0ac\uc5c5\ud65c\ub3d9 \ubc29\ud574\ud589\uc704"],t.s)
