B.a2v=s(["\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \uc815\ub2f9\ud589\uc704"],t.s)
B.aym=new A.b("gen_gn_scope_6","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc801\uc6a9\ubc94\uc704\xb7\uc801\uc6a9\uc81c\uc678","\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub978 \uc815\ub2f9\ud55c \ud589\uc704\uc640 \uacf5\uc815\uac70\ub798\ubc95 \uc801\uc6a9\uc81c\uc678\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.IR,0,"\ub2e4\ub978 \ubc95\ub839\uc5d0 \ub530\ub77c \ud589\ud558\ub294 \uc815\ub2f9\ud55c \ud589\uc704\uc5d0 \ub300\ud55c \uc801\uc6a9\uc81c\uc678\ub294 \uadf8 \ubc95\ub839\uc5d0 \uba85\uc2dc\uc801\uc774\uace0 \uad6c\uccb4\uc801\uc778 \uadfc\uac70\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \uc81c\ud55c\uc801\uc73c\ub85c \uc778\uc815\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \ub2e8\uc21c\ud788 \ub2e4\ub978 \ubc95\ub839\uc774 \uc874\uc7ac\ud55c\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \uacf5\uc815\uac70\ub798\ubc95 \uc801\uc6a9\uc774 \uc790\ub3d9\uc73c\ub85c \uc804\uba74 \ubc30\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uadf8 \ud589\uc704\uac00 \uc2e4\uc9c8\uc801\uc73c\ub85c \uacbd\uc7c1\uc744 \ubd80\ub2f9\ud558\uac8c \uc81c\ud55c\ud558\ub294\uc9c0 \uc5ec\ubd80\uac00 \ud568\uaed8 \uac80\ud1a0\ub41c\ub2e4.",B.Wo,B.a2v,null)
B.TN=s(["\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc77c\ubc18\ubc95\uc801 \uc9c0\uc704\ub97c \uac00\uc9c0\uba70, \uac1c\ubcc4 \ubc95\ub960\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0 \ud2b9\ud654\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c\uc11c \uc6b0\uc120 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uc740 \uacf5\uc815\uac70\ub798\ubc95\uacfc \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ubcc4\uac1c\uc758 \ub3c5\ub9bd\ub41c \ubc95\uccb4\uacc4\uc774\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uc774 \uc788\uc73c\uba74 \uacf5\uc815\uac70\ub798\ubc95\uc740 \ud574\ub2f9 \ubd84\uc57c\uc5d0\uc11c \uc644\uc804\ud788 \ud6a8\ub825\uc744 \uc0c1\uc2e4\ud55c\ub2e4","\uacf5\uc815\uac70\ub798\ubc95\uc774 \ud56d\uc0c1 \uac1c\ubcc4 \ubc95\ub960\uc5d0 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\uac1c\ubcc4 \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc740 \ub3d9\uc2dc\uc5d0 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.NJ=s(["\uac1c\ubcc4 \ubc95\ub960\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c\uc5d0 \ud2b9\ud654\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c\uc11c \uc6b0\uc120 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4"],t.s)
B.acS=s(["\uc77c\ubc18\ubc95\xb7\ud2b9\ubcc4\ubc95 \uad00\uacc4"],t.s)
B.aAF=new A.b("gen_gn_system_1","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uac00\ub9f9\uc0ac\uc5c5\uac70\ub798\uc758 \uacf5\uc815\ud654\uc5d0 \uad00\ud55c \ubc95\ub960, \ud558\ub3c4\uae09\uac70\ub798 \uacf5\uc815\ud654\uc5d0 \uad00\ud55c \ubc95\ub960 \ub4f1 \uac1c\ubcc4 \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.TN,0,"\uac00\ub9f9\uc0ac\uc5c5\ubc95\xb7\ud558\ub3c4\uae09\ubc95 \ub4f1\uc740 \ud2b9\uc815 \uac70\ub798\ubd84\uc57c(\uac00\ub9f9, \ud558\ub3c4\uae09 \ub4f1)\uc758 \ud2b9\uc131\uc744 \ubc18\uc601\ud574 \uacf5\uc815\uac70\ub798\ubc95\uc758 \uae30\ubcf8 \uc774\ub150 \uc544\ub798 \ub9c8\ub828\ub41c \ud2b9\ubcc4\ubc95\uc73c\ub85c, \ud574\ub2f9 \ubd84\uc57c\uc5d0\uc11c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\ubcc4\ubc95\uc774 \uc6b0\uc120 \uc801\uc6a9\ub41c\ub2e4. \ub2e4\ub9cc \uc774\ub4e4 \ubc95\ub960\ub3c4 \uad81\uadf9\uc801\uc73c\ub85c\ub294 \uacf5\uc815\uac70\ub798\ubc95\uc774 \ucd94\uad6c\ud558\ub294 \uacf5\uc815\ud558\uace0 \uc790\uc720\ub85c\uc6b4 \uacbd\uc7c1 \ucd09\uc9c4\uc774\ub77c\ub294 \uc774\ub150\uc744 \uacf5\uc720\ud558\uba70, \ub450 \ubc95\ub960\uc774 \uc0c1\ud638 \ubc30\ud0c0\uc801\uc73c\ub85c \ub2e8\uc808\ub41c \uac83\uc740 \uc544\ub2c8\ub2e4.",B.NJ,B.acS,null)
B.a9O=s(["\uc57d\uad00\ubc95\uc740 \ubd88\uacf5\uc815\uc57d\uad00 \uc2ec\uc0ac\ub97c \ubcc4\ub3c4\ub85c \uaddc\uc728\ud558\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uad00\uc758 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c \uacf5\uc815\uac70\ub798\ubc95\uacfc \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4","\uc57d\uad00\ubc95\uc740 \uacf5\uc815\uac70\ub798\ubc95\uacfc \uc804\ud600 \uad00\ub828 \uc5c6\ub294 \ub2e4\ub978 \uc815\ubd80\ubd80\ucc98 \uc18c\uad00 \ubc95\ub960\uc774\ub2e4","\uc57d\uad00\ubc95\uc774 \uc2dc\ud589\ub418\uba74 \uacf5\uc815\uac70\ub798\ubc95\uc0c1 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uaddc\uc815\uc740 \uc804\ubd80 \ud3d0\uc9c0\ub41c\ub2e4","\uc57d\uad00\ubc95\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc57d\uad00\uc5d0 \uad00\ud55c \uc0ac\ud56d\uc740 \uc624\uc9c1 \ubbfc\ubc95\uc73c\ub85c\ub9cc \uaddc\uc728\ub418\uace0 \uc57d\uad00\ubc95\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.X8=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uad00\uc758 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c \uacf5\uc815\uac70\ub798\ubc95\uacfc \ud568\uaed8 \uc791\ub3d9\ud55c\ub2e4"],t.s)
B.Ov=s(["\uc57d\uad00\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4"],t.s)
B.as1=new A.b("gen_gn_system_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a9O,0,"\uc57d\uad00\uc758 \uaddc\uc81c\uc5d0 \uad00\ud55c \ubc95\ub960\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc18c\uad00\ud558\ub294 \uac1c\ubcc4 \ubc95\ub960\ub85c\uc11c, \uc0ac\uc5c5\uc790\uac00 \ubbf8\ub9ac \ub9c8\ub828\ud55c \uc57d\uad00 \uc870\ud56d\uc758 \ubd88\uacf5\uc815\uc131\uc744 \uc2ec\uc0ac\xb7\uaddc\uc81c\ud558\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uacfc\ub294 \uaddc\uc728 \ub300\uc0c1\uacfc \uc694\uac74\uc774 \ub2e4\ub974\uc9c0\ub9cc, \uac19\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uccb4\uacc4 \uc548\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uc791\ub3d9\ud558\ub294 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.X8,B.Ov,null)
B.aam=s(["\ub450 \ubc95\ub960\uc740 \ubaa9\uc801\uacfc \ubcf4\ud638\ubc95\uc775\uc758 \uac15\uc870\uc810\uc774 \ub2e4\ub974\uc9c0\ub9cc \uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uce21\uba74\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc774 \uc2dc\ud589\ub41c \uc774\ud6c4 \uacf5\uc815\uac70\ub798\ubc95\uc740 \ud3d0\uc9c0\ub418\uc5c8\ub2e4","\ub450 \ubc95\ub960\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ub0b4\uc6a9\uc744 \uaddc\uc815\ud558\uace0 \uc788\uc5b4 \ud558\ub098\ub9cc \uc874\uc7ac\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc740 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\uace0 \uc18c\ube44\uc790\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc18c\ube44\uc790 \uad00\ub828 \uc0ac\ud56d\uc744 \uc804\ud600 \ub2e4\ub8e8\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a3f=s(["\uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uce21\uba74\uc5d0\uc11c \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4"],t.s)
B.a_h=s(["\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uacfc\uc758 \uad00\uacc4"],t.s)
B.azP=new A.b("gen_gn_system_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4","\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uacfc \uacf5\uc815\uac70\ub798\ubc95\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aam,0,"\uc18c\ube44\uc790\uae30\ubcf8\ubc95\uc740 \uc18c\ube44\uc790\uc758 \uad8c\uc775 \uc99d\uc9c4\uacfc \ud53c\ud574\uad6c\uc81c\ub97c \uc9c1\uc811\uc801 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ubc18\uba74, \uacf5\uc815\uac70\ub798\ubc95\uc740 \uacbd\uc7c1 \ucd09\uc9c4\uc744 \ud1b5\ud55c \uad6c\uc870\uc801\xb7\uac04\uc811\uc801 \uc18c\ube44\uc790\ud6c4\uc0dd \uc99d\uc9c4\uc5d0 \ubc29\uc810\uc774 \uc788\ub2e4. \ub450 \ubc95\ub960\uc740 \uac15\uc870\uc810\uc774 \ub2e4\ub974\uc9c0\ub9cc \uad81\uadf9\uc801\uc73c\ub85c \uc18c\ube44\uc790 \ud6c4\uc0dd \uc99d\uc9c4\uc774\ub77c\ub294 \uacf5\ud1b5\uc758 \uc9c0\ud5a5\uc810\uc744 \uac00\uc9c0\uace0 \uc0c1\ud638 \ubcf4\uc644\uc801\uc73c\ub85c \uae30\ub2a5\ud55c\ub2e4.",B.a3f,B.a_h,null)
B.ajw=s(["\ub3d9\uc77c\ud55c \uc0ac\uc548\uc5d0 \ub300\ud574 \ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8 \ud2b9\ubcc4\ubc95 \uaddc\uc815\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4","\ud2b9\ubcc4\ubc95\uacfc \uc77c\ubc18\ubc95\uc774 \ucda9\ub3cc\ud558\uba74 \ud56d\uc0c1 \uc77c\ubc18\ubc95\uc774 \uc6b0\uc120\ud55c\ub2e4","\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \uacf5\uc815\uac70\ub798\ubc95 \uccb4\uacc4\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud2b9\ubcc4\ubc95\uc774 \uc788\uc73c\uba74 \uc77c\ubc18\ubc95\uc740 \uadf8 \uc989\uc2dc \uc804\uccb4\uac00 \ud3d0\uc9c0\ub41c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59\uc740 \ud615\ubc95\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ud589\uc815\ubc95 \ubd84\uc57c\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.afN=s(["\ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\uc73c\uba74 \uadf8 \ud2b9\ubcc4\ubc95 \uaddc\uc815\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.a2g=s(["\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59"],t.s)
B.asV=new A.b("gen_gn_system_4","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\ubc95 \uccb4\uacc4\xb7\ub2e4\ub978 \ubc95\ub960\uacfc\uc758 \uad00\uacc4",'"\ud2b9\ubcc4\ubc95 \uc6b0\uc120\uc758 \uc6d0\uce59"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.ajw,0,'"\ud2b9\ubcc4\ubc95\uc740 \uc77c\ubc18\ubc95\uc5d0 \uc6b0\uc120\ud55c\ub2e4"\ub294 \ubc95 \uc801\uc6a9\uc758 \uc77c\ubc18\uc6d0\uce59\uc73c\ub85c, \ub3d9\uc77c\ud55c \uc0ac\ud56d\uc5d0 \ub300\ud574 \ud2b9\ubcc4\ubc95\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud2b9\ubcc4\ubc95\uc774 \uc77c\ubc18\ubc95\ubcf4\ub2e4 \uc6b0\uc120\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4. \uacf5\uc815\uac70\ub798\ubc95\uacfc \uac00\ub9f9\uc0ac\uc5c5\ubc95\xb7\ud558\ub3c4\uae09\ubc95 \ub4f1\uc758 \uad00\uacc4\uc5d0\uc11c\ub3c4 \uc774 \uc6d0\ufffd\ub9ac\uc774 \uc801\uc6a9\ub418\uc5b4, \ud574\ub2f9 \ud2b9\ubcc4\ubc95\uc774 \uaddc\uc728\ud558\ub294 \uc0ac\ud56d\uc5d0\ub294 \ud2b9\ubcc4\ubc95\uc774 \uba3c\uc800 \uc801\uc6a9\ub41c\ub2e4.',B.afN,B.a2g,null)
B.af8=s(["\ud53c\ud574\uc790\ub294 \uacf5\uc815\uac70\ub798\ubc95 \ubc0f \ubbfc\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1 \uad00\ub828 \uaddc\uc815 \ub4f1\uc744 \ud1b5\ud574 \uac00\ud574 \uc0ac\uc5c5\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18\uc5d0 \ub300\ud574\uc11c\ub294 \uc5b4\ub5a0\ud55c \ubbfc\uc0ac\uc801 \uad6c\uc81c\uc218\ub2e8\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbfc\uc0ac\uc801 \uad6c\uc81c\ub294 \ubc18\ub4dc\uc2dc \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc0ac\uc804 \ucc98\ubd84\uc774 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc778\uc815\ub41c\ub2e4","\uacf5\uc815\uac70\ub798\ubc95 \uc704\ubc18 \ud53c\ud574\uc790\ub294 \ud615\uc0ac\uace0\uc18c\ub9cc \uac00\ub2a5\ud558\uace0 \ubbfc\uc0ac\uc18c\uc1a1\uc740 \uc81c\uae30\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.W1=s(["\uacf5\uc815\uac70\ub798\ubc95 \ubc0f \ubbfc\ubc95\uc0c1 \uc190\ud574\ubc30\uc0c1 \uad00\ub828 \uaddc\uc815 \ub4f1\uc744 \ud1b5\ud574 \uac00\ud574 \uc0ac\uc5c5\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
