B.apD=new A.b("gen_collusion_end_5","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\uacf5\ub3d9\ud589\uc704\uc758 \uc885\ub8cc\xb7\uac1c\ubcc4 \uc0ac\uc5c5\uc790 \ucc45\uc784","\uacf5\ub3d9\ud589\uc704 \uc885\ub8cc \uc2dc\uc810 \ud310\ub2e8\uc774 \ucc98\ubd84\uc2dc\ud6a8\uc640 \uac16\ub294 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a83,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704 \uc0ac\uac74\uc5d0\uc11c \uc885\uae30(\uc2e4\ud589\ud589\uc704\uac00 \ucd5c\uc885\uc801\uc73c\ub85c \uc885\ub8cc\ub41c \uc2dc\uc810)\ub97c \uc5b8\uc81c\ub85c \ubcfc \uac83\uc778\uc9c0\uc5d0 \ub530\ub77c \ucc98\ubd84\uc2dc\ud6a8\uc758 \uae30\uc0b0\uc810\uc774 \ub2ec\ub77c\uc9c8 \uc218 \uc788\uc5b4, \uc774\ub294 \uc2e4\ubb34\uc0c1 \ub2e4\ud22c\uc5b4\uc9c0\ub294 \uc911\uc694\ud55c \uc7c1\uc810 \uc911 \ud558\ub098\uc774\ub2e4.",B.aj6,B.Vx,null)
B.a7T=s(["\uc704\uc6d0\ud68c\ub294 \uc704\uc6d0\uc7a5 1\uba85, \ubd80\uc704\uc6d0\uc7a5 1\uba85\uc744 \ud3ec\ud568\ud55c 9\uba85\uc758 \uc704\uc6d0\uc73c\ub85c \uad6c\uc131\ud55c\ub2e4","\uc704\uc6d0\uc7a5\uacfc \ubd80\uc704\uc6d0\uc7a5\uc740 \uc815\ubb34\uc9c1 \uacf5\ubb34\uc6d0\uc73c\ub85c \uc784\uba85\ud55c\ub2e4","\uc704\uc6d0 \uc911 4\uba85\uc740 \uc0c1\uc784\uc704\uc6d0, 4\uba85\uc740 \ube44\uc0c1\uc784\uc704\uc6d0\uc73c\ub85c \ud55c\ub2e4","\uc704\uc6d0\uc740 \ubaa8\ub450 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5\xb7\ub2e4\ub978 \uc704\uc6d0\uc740 \uad6d\ubb34\ucd1d\ub9ac\uc758 \uc81c\uccad\uc73c\ub85c \ub300\ud1b5\ub839\uc774 \uc784\uba85 \ub610\ub294 \uc704\ucd09\ud55c\ub2e4"],t.s)
B.afk=s(["\uc704\uc6d0\uc740 \ubaa8\ub450 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.Rv=s(["\uc704\uc6d0\ud68c \uad6c\uc131 \uc778\uc6d0"],t.s)
B.ayR=new A.b("gen_ftc_org_comp_1","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uad6c\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a7T,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc704\uc6d0\uc7a5 1\uba85\uacfc \ubd80\uc704\uc6d0\uc7a5 1\uba85\uc744 \ud3ec\ud568\ud55c 9\uba85\uc758 \uc704\uc6d0(\uc0c1\uc784\uc704\uc6d0 4\uba85, \ube44\uc0c1\uc784\uc704\uc6d0 4\uba85)\uc73c\ub85c \uad6c\uc131\ub418\uba70, \uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5\uc740 \uc815\ubb34\uc9c1 \uacf5\ubb34\uc6d0\uc73c\ub85c \uad6d\ubb34\ucd1d\ub9ac\uc758 \uc81c\uccad\uc744 \uac70\uccd0 \ub300\ud1b5\ub839\uc774 \uc784\uba85\ud55c\ub2e4. \uc704\uc6d0\uc740 \uad6d\ud68c\uc758\uc6d0\uc744 \uacb8\uc9c1\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uba70, "\ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758\uc6d0 \uc2e0\ubd84\uc744 \uacb8\uc9c1\ud558\uc5ec\uc57c \ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.afk,B.Rv,null)
B.OO=s(["\uc704\uc6d0\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uba70, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 \uc885\uc2e0\uc73c\ub85c \ud55c\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 1\ub144\uc774\uba70 \uc5f0\uc784\ud560 \uc218 \uc5c6\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\ub294 \ub300\ud1b5\ub839\uc758 \uc784\uae30\uc640 \uc5f0\ub3d9\ub418\uc5b4 \uc790\ub3d9\uc73c\ub85c \ubcc0\uacbd\ub41c\ub2e4","\uc704\uc6d0\uc758 \uc784\uae30\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.agQ=s(["\uc704\uc6d0\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uba70, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ZT=s(["\uc704\uc6d0\uc758 \uc784\uae30"],t.s)
B.aCD=new A.b("gen_ftc_org_comp_2","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc784\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.OO,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0(\uc704\uc6d0\uc7a5\xb7\ubd80\uc704\uc6d0\uc7a5 \ud3ec\ud568)\uc758 \uc784\uae30\ub294 3\ub144\uc73c\ub85c \ud558\uace0, 1\ucc28\uc5d0 \ud55c\ud558\uc5ec \uc5f0\uc784\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc704\uc6d0\ud68c\uc758 \ub3c5\ub9bd\uc131\uacfc \uc804\ubb38\uc131\uc744 \ud655\ubcf4\ud558\uba74\uc11c\ub3c4 \uc9c0\ub098\uce5c \uc7a5\uae30 \uc7ac\uc784\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.agQ,B.ZT,null)
B.a4x=s(["\uc704\uc6d0\uc740 \uae08\uace0 \uc774\uc0c1\uc758 \ud615\uc744 \uc120\uace0\ubc1b\uc740 \uacbd\uc6b0\uac00 \uc544\ub2c8\uba74 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \uba74\uc9c1\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc704\uc6d0\uc740 \ud0c4\ud575\uacb0\uc815\uc73c\ub85c \ud30c\uba74\ub420 \uc218 \uc788\ub2e4","\uc7a5\uae30\uac04 \uc2ec\uc2e0\uc1e0\uc57d\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \uacbd\uc6b0 \ub4f1 \ubc95\uc5d0\uc11c \uc815\ud55c \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uba74\uc9c1\ub420 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc740 \uc815\uce58\uc801 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4","\uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5\uc740 \uc704\uc6d0\ud68c\uc758 \ub3c5\ub9bd\uc801\xb7\uc911\ub9bd\uc801 \uc9c1\ubb34\uc218\ud589\uc744 \ub4b7\ubc1b\uce68\ud558\uae30 \uc704\ud55c \uc7a5\uce58\uc774\ub2e4"],t.s)
B.Hs=s(["\uc704\uc6d0\uc740 \uc815\uce58\uc801 \uc0ac\uc815\uc5d0 \ub530\ub77c \uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aer=s(["\uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5"],t.s)
B.aAP=new A.b("gen_ftc_org_comp_3","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc2e0\ubd84\ubcf4\uc7a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a4x,3,'\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc740 \ud0c4\ud575\uacb0\uc815\uc73c\ub85c \ud30c\uba74\ub418\uac70\ub098 \uae08\uace0 \uc774\uc0c1\uc758 \ud615\uc744 \uc120\uace0\ubc1b\uac70\ub098 \uc7a5\uae30\uac04 \uc2ec\uc2e0\uc1e0\uc57d\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud560 \uc218 \uc5c6\uac8c \ub418\ub294 \ub4f1 \ubc95\uc5d0\uc11c \uc815\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \uc544\ub2c8\uba74 \ubcf8\uc778\uc758 \uc758\uc0ac\uc5d0 \ubc18\ud558\uc5ec \uba74\uc9c1\ub418\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub7ec\ud55c \uc2e0\ubd84\ubcf4\uc7a5\uc740 \uc704\uc6d0\ud68c\uac00 \uc815\uce58\uc801 \uc555\ub825\uc5d0\uc11c \ubc97\uc5b4\ub098 \ub3c5\ub9bd\uc801\xb7\uc911\ub9bd\uc801\uc73c\ub85c \uc9c1\ubb34\ub97c \uc218\ud589\ud558\ub3c4\ub85d \ud558\uae30 \uc704\ud55c \uac83\uc73c\ub85c, "\uc544\ubb34 \ub54c\ub098 \uc784\uc758\ub85c \ud574\uc784\ub420 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.Hs,B.aer,null)
B.akb=s(["\ubc95\ub960\xb7\uacbd\uc81c\xb7\uacbd\uc601 \ub4f1\uc758 \ubd84\uc57c\uc5d0\uc11c \ud559\uc2dd\uacfc \uacbd\ud5d8\uc774 \ud48d\ubd80\ud55c \uc0ac\ub78c","\uacf5\uc815\uac70\ub798 \uad00\ub828 \uc0ac\uac74\uc744 \ub2e4\ub8e8\uc5b4 \ubcf8 \ud310\uc0ac\xb7\uac80\uc0ac \ub610\ub294 \ubcc0\ud638\uc0ac \uacbd\ub825\uc774 \uc788\ub294 \uc0ac\ub78c","\uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \uc0ac\ubb34\uc5d0 \uc885\uc0ac\ud55c 3\uae09 \uc774\uc0c1 \uacf5\ubb34\uc6d0 \uacbd\ub825\uc774 \uc788\ub294 \uc0ac\ub78c","\ubc18\ub4dc\uc2dc \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc790\uaca9","\uacbd\uc81c \uad00\ub828 \uc5f0\uad6c\uae30\uad00\uc5d0\uc11c \ubd80\uad50\uc218\uae09 \uc774\uc0c1\uc758 \uc9c1\uc5d0 \uc788\uc5c8\ub358 \uc0ac\ub78c"],t.s)
B.ad4=s(["\ubc18\ub4dc\uc2dc \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc790\uaca9"],t.s)
B.UN=s(["\uc704\uc6d0\uc758 \uc790\uaca9\uc694\uac74"],t.s)
B.az9=new A.b("gen_ftc_org_comp_4","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc758 \uc790\uaca9\uc694\uac74\uc73c\ub85c \ubc95\uc5d0\uc11c \uc694\uad6c\ud558\ub294 \uac83\uacfc \uac00\uc7a5 \uac70\ub9ac\uac00 \uba3c \uac83\uc740?",B.akb,3,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc704\uc6d0\uc740 \ubc95\ub960\xb7\uacbd\uc81c\xb7\uacbd\uc601 \ub4f1\uc758 \ubd84\uc57c\uc758 \ud559\uc2dd\uacfc \uacbd\ud5d8, \ud310\uc0ac\xb7\uac80\uc0ac\xb7\ubcc0\ud638\uc0ac \uacbd\ub825, \uace0\uc704 \uacf5\ubb34\uc6d0 \uacbd\ub825, \uc5f0\uad6c\uae30\uad00 \uacbd\ub825 \ub4f1 \uc804\ubb38\uc131\uc744 \uae30\uc900\uc73c\ub85c \uc784\uba85\xb7\uc704\ucd09\ub41c\ub2e4. \ud2b9\uc815 \uc815\ub2f9\uc758 \ub2f9\uc6d0 \uc5ec\ubd80\ub294 \uc704\uc6d0 \uc790\uaca9\uc694\uac74\uc73c\ub85c \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc73c\uba70, \uc624\ud788\ub824 \uc704\uc6d0\ud68c\uc758 \uc815\uce58\uc801 \uc911\ub9bd\uc131\uc774 \uac15\uc870\ub41c\ub2e4.",B.ad4,B.UN,null)
B.P7=s([u.yp,"\uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uad8c\ud55c\uacfc \uc758\uacb0\uad8c\uc5d0 \uc788\uc5b4 \uc804\ud600 \ucc28\uc774\uac00 \uc5c6\uc5b4 \uad6c\ubcc4\uc758 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\ube44\uc0c1\uc784\uc704\uc6d0\ub9cc \uc758\uacb0\uad8c\uc744 \uac00\uc9c0\uace0 \uc0c1\uc784\uc704\uc6d0\uc740 \uc758\uacb0\uad8c\uc774 \uc5c6\ub2e4","\uc0c1\uc784\uc704\uc6d0\uc740 \ubbfc\uac04\uc778\ub9cc, \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uacf5\ubb34\uc6d0\ub9cc \uc784\uba85\ub420 \uc218 \uc788\ub2e4","\uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc758 \uad6c\ubd84\uc740 \ubc95\ub960\uc0c1 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
