B.aAa=new A.b("gen_ftc_org_comp_5","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc0c1\uc784\uc704\uc6d0\uacfc \ube44\uc0c1\uc784\uc704\uc6d0\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.P7,0,"\uc0c1\uc784\uc704\uc6d0\uc740 \uc704\uc6d0\ud68c\uc5d0 \uc0c1\uc2dc \uadfc\ubb34\ud558\uba70 \uc5c5\ubb34\uc5d0 \uc804\ub150\ud558\ub294 \ubc18\uba74, \ube44\uc0c1\uc784\uc704\uc6d0\uc740 \uc0c1\uc2dc \uadfc\ubb34 \uc758\ubb34 \uc5c6\uc774 \ud68c\uc758 \ub4f1 \ud544\uc694\ud55c \uacbd\uc6b0\uc5d0 \uc9c1\ubb34\ub97c \uc218\ud589\ud55c\ub2e4. \ub2e4\ub9cc \uc758\uacb0\uc5d0 \ucc38\uc5ec\ud560 \ub54c\ub294 \uc0c1\uc784\uc704\uc6d0\xb7\ube44\uc0c1\uc784\uc704\uc6d0 \ubaa8\ub450 \ub3d9\ub4f1\ud55c \uc758\uacb0\uad8c\uc744 \uac00\uc9c4\ub2e4.",B.a09,B.a7I,null)
B.a6t=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uad6d\ubb34\ucd1d\ub9ac \uc18c\uc18d\uc758 \uc911\uc559\ud589\uc815\uae30\uad00\uc73c\ub85c\uc11c \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc0ac\ubc95\ubd80\uc5d0 \uc18c\uc18d\ub41c \ubc95\uc6d0\uc758 \uc77c\uc885\uc774\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc21c\uc218 \ubbfc\uac04\ub2e8\uccb4\ub85c\uc11c \uc544\ubb34\ub7f0 \ud589\uc815\uad8c\ud55c\uc774 \uc5c6\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uc9c0\ubc29\uc790\uce58\ub2e8\uccb4 \uc0b0\ud558 \uae30\uad00\uc774\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uad6d\ud68c\uc5d0 \uc18c\uc18d\ub41c \ubcf4\uc870\uae30\uad00\uc774\ub2e4"],t.s)
B.a9y=s(["\uad6d\ubb34\ucd1d\ub9ac \uc18c\uc18d\uc758 \uc911\uc559\ud589\uc815\uae30\uad00\uc73c\ub85c\uc11c \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.a0c=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ubc95\uc801 \uc131\uaca9"],t.s)
B.avy=new A.b("gen_ftc_org_comp_6","economic_law","\uc704\uc6d0\ud68c \uad6c\uc131\xb7\ud68c\uc758","\uc704\uc6d0\ud68c\uc758 \uad6c\uc131","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ubc95\uc801 \uc131\uaca9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a6t,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \uad6d\ubb34\ucd1d\ub9ac \uc18c\uc18d\uc73c\ub85c \uc124\uce58\ub41c \uc911\uc559\ud589\uc815\uae30\uad00\uc73c\ub85c\uc11c, \ub2e4\uc218\uc758 \uc704\uc6d0\uc774 \ud569\uc758\ub97c \ud1b5\ud574 \uc758\uc0ac\ub97c \uacb0\uc815\ud558\ub294 \ud569\uc758\uc81c \ud589\uc815\uae30\uad00\uc758 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4. \uc774\ub7ec\ud55c \ud569\uc758\uc81c \uad6c\uc870\ub294 \ud2b9\uc815 \uac1c\uc778\uc758 \uc790\uc758\uc801 \ud310\ub2e8\uc744 \uacac\uc81c\ud558\uace0 \uc804\ubb38\uc131\xb7\uacf5\uc815\uc131\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4.",B.a9y,B.a0c,null)
B.af1=s(["\ud68c\uc758\ub294 \uc704\uc6d0 \uc804\uc6d0\uc73c\ub85c \uad6c\uc131\ud558\ub294 \uc804\uc6d0\ud68c\uc758\uc640 \uc77c\ubd80 \uc704\uc6d0\uc73c\ub85c \uad6c\uc131\ud558\ub294 \uc18c\ud68c\uc758\ub85c \uad6c\ubd84\ub41c\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ud68c\uc758\ub294 \uc804\uc6d0\ud68c\uc758 \ud55c \uc885\ub958\ub9cc \uc874\uc7ac\ud55c\ub2e4","\uc18c\ud68c\uc758\ub294 \ube44\uc0c1\uc784\uc704\uc6d0\ub9cc\uc73c\ub85c \uad6c\uc131\ub41c\ub2e4","\uc804\uc6d0\ud68c\uc758\uc640 \uc18c\ud68c\uc758\ub294 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uae30\uad00\uc774\ub2e4","\ud68c\uc758\uc758 \uc885\ub958\uc5d0 \uad00\ud55c \uc0ac\ud56d\uc740 \uc704\uc6d0\uc7a5\uc774 \ub9e4\ubc88 \uc784\uc758\ub85c \uc815\ud55c\ub2e4"],t.s)
