B.axe=new A.b("gen_dmg_proc_4","economic_law","\uc190\ud574\ubc30\uc0c1\ucc45\uc784","\uc790\ub8cc\uc81c\ucd9c\uba85\ub839\xb7\uae30\ub85d\uc1a1\ubd80\uc694\uad6c \ub4f1 \uc808\ucc28","\uc790\ub8cc\uc81c\ucd9c\uba85\ub839\uc758 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub420 \uc218 \uc788\ub294 \uc790\ub8cc\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.a_M,0,"\uc790\ub8cc\uc81c\ucd9c\uba85\ub839\uc740 \uc190\ud574\uc758 \uc99d\uba85\xb7\uc190\ud574\uc561 \uc0b0\uc815\uc744 \uc704\ud574 \ud3ed\ub113\uac8c \uc778\uc815\ub418\uc9c0\ub9cc, \uadf8 \uc790\ub8cc\uac00 \uc601\uc5c5\ube44\ubc00\uc5d0 \ud574\ub2f9\ud558\uace0 \uc81c\ucd9c\ub85c \uc778\ud55c \uc601\uc5c5\ube44\ubc00 \uce68\ud574\uc758 \uc6b0\ub824\uac00 \uc790\ub8cc\uc758 \ud544\uc694\uc131\ubcf4\ub2e4 \ud06c\ub2e4\uace0 \uc778\uc815\ub418\ub294 \ub4f1 \uc815\ub2f9\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc81c\ucd9c\uc758\ubb34\uac00 \uc81c\ud55c\ub420 \uc218 \uc788\ub2e4.",B.a2i,B.afw,null)
