B.axZ=new A.b("gen_conc_6","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uacfc \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Ps,0,"\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45\uc774 \uc0c1\ud638\ucd9c\uc790 \uae08\uc9c0, \uc21c\ud658\ucd9c\uc790 \uc81c\ud55c, \ucc44\ubb34\ubcf4\uc99d \uc81c\ud55c, \uc9c0\uc8fc\ud68c\uc0ac \uaddc\uc81c \ub4f1\uc744 \ud1b5\ud574 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uc9c0\ubc30\uad6c\uc870 \uc790\uccb4\ub97c \uad6c\uc870\uc801\uc73c\ub85c \uaddc\uc81c\ud558\ub294 \uac83\uc774\ub77c\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\ub294 \uadf8\ub7ec\ud55c \uad6c\uc870 \ud558\uc5d0\uc11c \ucd1d\uc218 \uc77c\uac00 \ub4f1 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\ub2f9\ud55c \uc774\uc775\uc774 \uac1c\ubcc4\uc801\uc73c\ub85c \uadc0\uc18d\ub418\ub294 \ud589\uc704\ub97c \uaddc\uc81c\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c, \ub450 \uc81c\ub3c4\ub294 \ub300\uae30\uc5c5\uc9d1\ub2e8\uc758 \uacbd\uc81c\ub825\uc9d1\uc911\uc774\ub77c\ub294 \uacf5\ud1b5\ub41c \ubb38\uc81c\ub97c \uc11c\ub85c \ub2e4\ub978 \uce35\uc704\uc5d0\uc11c \ub2e4\ub8e8\ub294 \ubcf4\uc644\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4.",B.a6y,B.MO,null)
B.ag0=s(["\ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \ub9cc\ub4e4\uc5b4 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\uc600\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud574 \uc138\ud615 \ub3d9\uac80\uc744 \uc81c\uc791\ud558\uc600\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\ub85c \uc774\uc0ad\uc744 \uc798\ub77c \ubcbc\ub18d\uc0ac\ub97c \uc9c0\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc744 \ub9cc\ub4e4\uc5b4 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \ub098\ud0c0\ub0b4\uc5c8\ub2e4"],t.s)
B.aiQ=s(["\ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4"],t.s)
B.XE=s(["\uad6c\uc11d\uae30\uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5"],t.s)
B.arR=new A.b("gen_kh_prehist_1","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc774 \uc0ac\uc6a9\ub41c \uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\uc5f0\ucc9c \uc804\uace1\ub9ac \uc720\uc801\uc5d0\uc11c\ub294 \uc544\uc290\ub9ac\uc548\ud615 \uc8fc\uba39\ub3c4\ub07c\ub97c \ube44\ub86f\ud55c \ub5c0\uc11d\uae30\uac00 \ub2e4\uc218 \ucd9c\ud1a0\ub418\uc5c8\ub2e4."',B.ag0,0,"\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\ub97c \uc0ac\uc6a9\ud55c \uc2dc\ub300\ub294 \uad6c\uc11d\uae30\uc2dc\ub300\uc774\ub2e4. \uad6c\uc11d\uae30\uc778\ub4e4\uc740 \ub3d9\uad74\uc774\ub098 \ub9c9\uc9d1\uc5d0 \uc0b4\uba74\uc11c \uc0ac\ub0e5\uacfc \ucc44\uc9d1\uc744 \uc704\ud574 \ubb34\ub9ac\ub97c \uc9c0\uc5b4 \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\uc600\ub2e4. \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\xb7\uac04\uc11d\uae30\ub294 \uc2e0\uc11d\uae30, \uac70\ud478\uc9d1\xb7\uc138\ud615\ub3d9\uac80\uc740 \ucca0\uae30, \ubc18\ub2ec\ub3cc\uce7c\xb7\uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aiQ,B.XE,null)
B.ajS=s(["\uac00\ub77d\ubc14\ud034\ub85c \uc2e4\uc744 \ubf51\uace0 \ubf08\ubc14\ub298\ub85c \uc637\uc744 \uc9c0\uc5b4 \uc785\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\ub97c \ucc98\uc74c\uc73c\ub85c \uc81c\uc791\ud558\uc600\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc0dd\uc0b0\ub825\uc744 \ud06c\uac8c \ub192\uc600\ub2e4","\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uc744 \uc758\ub840 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uad70\uc7a5\uc774 \ub4f1\uc7a5\ud558\uc5ec \uacc4\uae09 \uc0ac\ud68c\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4"],t.s)
B.Vb=s(["\uac00\ub77d\ubc14\ud034\ub85c \uc2e4\uc744 \ubf51\uace0 \ubf08\ubc14\ub298\ub85c \uc637\uc744 \uc9c0\uc5b4 \uc785\uc5c8\ub2e4"],t.s)
B.Oq=s(["\uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5"],t.s)
B.aCj=new A.b("gen_kh_prehist_2","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'(\uac00) \uc2dc\ub300\uc758 \uc0dd\ud65c \ubaa8\uc2b5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\uc11c\uc6b8 \uc554\uc0ac\ub3d9 \uc720\uc801\uc5d0\uc11c\ub294 (\uac00) \uc2dc\ub300\ub97c \ub300\ud45c\ud558\ub294 \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\uc640 \uac08\ub3cc\xb7\uac08\ud310\uc774 \ucd9c\ud1a0\ub418\uc5c8\ub2e4."',B.ajS,0,"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub294 \uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \ub300\ud45c \uc720\ubb3c\uc774\ub2e4. \uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uacbd\uacfc \ubaa9\ucd95\uc774 \uc2dc\uc791\ub418\uc5b4 \uc815\ucc29 \uc0dd\ud65c\uc744 \ud558\uc600\uace0, \uac00\ub77d\ubc14\ud034\uc640 \ubf08\ubc14\ub298\uc744 \uc774\uc6a9\ud574 \uc637\uc774\ub098 \uadf8\ubb3c\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \ub5c0\uc11d\uae30 \ucd5c\ucd08 \uc81c\uc791\uc740 \uad6c\uc11d\uae30, \ucca0\uc81c \ub18d\uae30\uad6c\xb7\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\xb7\uad70\uc7a5\uc758 \ub4f1\uc7a5\uc740 \uccad\ub3d9\uae30~\ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.Vb,B.Oq,null)
B.a_i=s(["\ub18d\uacbd\uacfc \uc815\ucc29 \uc0dd\ud65c\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc528\uc871 \uc911\uc2ec\uc758 \ud3c9\ub4f1 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4","\uccad\ub3d9\uc81c \ubb34\uae30\ub97c \ub3c5\uc810\ud55c \uad70\uc7a5\uc774 \uc8fc\ubcc0 \ubd80\uc871\uc744 \uc815\ubcf5\ud558\uc600\ub2e4","\ud55c\uc790\uc640 \uc720\ud559\uc774 \uc804\ub798\ub418\uc5b4 \uc9c0\ubc30 \uc774\ub150\uc73c\ub85c \uc790\ub9ac \uc7a1\uc558\ub2e4","\uc911\uad6d \ud654\ud3d0\uc778 \uba85\ub3c4\uc804\uc774 \ub110\ub9ac \uc720\ud1b5\ub418\uc5c8\ub2e4","\uc655\uc704\uac00 \ubd80\uc790 \uc0c1\uc18d\uc73c\ub85c \uc138\uc2b5\ub418\ub294 \uc655\uad8c \uad6d\uac00\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4"],t.s)
B.ahh=s(["\ub18d\uacbd\uacfc \uc815\ucc29 \uc0dd\ud65c\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \uc528\uc871 \uc911\uc2ec\uc758 \ud3c9\ub4f1 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4"],t.s)
B.ajh=s(["\uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc0ac\ud68c \uc131\uaca9"],t.s)
B.auE=new A.b("gen_kh_prehist_3","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0 \ucc98\uc74c \ub098\ud0c0\ub09c \uc0ac\ud68c \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_i,0,"\uc2e0\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uacbd\uacfc \ubaa9\ucd95\uc774 \uc2dc\uc791\ub418\uba74\uc11c \uc815\ucc29 \uc0dd\ud65c\uc774 \uac00\ub2a5\ud574\uc84c\uace0, \uc528\uc871\uc744 \ub2e8\uc704\ub85c \ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9\uccb4 \uc0ac\ud68c\uac00 \ud615\uc131\ub418\uc5c8\ub2e4. \uacc4\uae09 \ubd84\ud654\uc640 \uc815\ubcf5 \uc804\uc7c1, \uc655\uad8c \uad6d\uac00\uc758 \uc131\ub9bd\uc740 \uccad\ub3d9\uae30\uc2dc\ub300 \uc774\ud6c4\uc5d0 \ub098\ud0c0\ub09c\ub2e4.",B.ahh,B.ajh,null)
B.ai1=s(["\uc2b4\ubca0\ucc0c\ub974\uac1c\ub294 \ucc3d\uc758 \uc790\ub8e8\uc5d0 \uaf42\uc544 \uc0ac\ub0e5 \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub294 \uc0ac\ub0e5\uacfc \uc870\ub9ac \ub4f1 \uc5ec\ub7ec \uc6a9\ub3c4\ub85c \uc4f0\uc778 \ub5c0\uc11d\uae30\uc774\ub2e4","\ucc0d\uac1c\ub294 \ub3cc\uc758 \ud55c\ucabd \uba74\uc744 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30\uc774\ub2e4","\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4","\ub5c0\uc11d\uae30\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub3c4\uad6c\uc774\ub2e4"],t.s)
B.Qd=s(["\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud558\uc5ec \ub3c4\uad6c\ub97c \ub300\ub7c9\uc73c\ub85c \uc8fc\uc870\ud558\uc600\ub2e4"],t.s)
B.acc=s(["\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc758 \ud2b9\uc9d5"],t.s)
B.arI=new A.b("gen_kh_prehist_4","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uad6c\uc11d\uae30\uc2dc\ub300 \ub3c4\uad6c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ai1,3,"\uac70\ud478\uc9d1\uc744 \uc774\uc6a9\ud55c \ub3c4\uad6c \uc8fc\uc870\ub294 \uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300\uc758 \uae08\uc18d \uac00\uacf5 \ubc29\uc2dd\uc774\ub2e4. \uad6c\uc11d\uae30\uc2dc\ub300\uc5d0\ub294 \ub3cc\uc744 \uae68\ub728\ub9ac\uac70\ub098 \ub5bc\uc5b4 \ub0b4\uc5b4 \ub9cc\ub4e0 \ub5c0\uc11d\uae30(\uc8fc\uba39\ub3c4\ub07c\xb7\ucc0d\uac1c\xb7\uc2b4\ubca0\ucc0c\ub974\uac1c \ub4f1)\ub97c \uc0ac\uc6a9\ud558\uc600\ub2e4.",B.Qd,B.acc,null)
B.a9p=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4","\uc774\ub3d9 \uc0dd\ud65c\uc5d0 \uc720\ub9ac\ud558\ub3c4\ub85d \uac00\ubcbc\uc6b4 \ucc9c\ub9c9 \ud615\ud0dc\uc758 \uc9d1\uc744 \uc8fc\ub85c \uc0ac\uc6a9\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ud06c\uac8c \ud5a5\uc0c1\ub418\uc5c8\ub2e4","\ubcbc\ub18d\uc0ac\uac00 \uc804\uad6d\uc801\uc73c\ub85c \ud655\ub300\ub418\uc5b4 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ucd95\uc801\ub418\uc5c8\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uac1c\uac04\uc774 \ud65c\ubc1c\ud574\uc838 \uacbd\uc9c0\uac00 \ud655\ub300\ub418\uc5c8\ub2e4"],t.s)
B.Ql=s(["\uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29\ud558\uc5ec \ub18d\uacbd\uacfc \uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4"],t.s)
B.O5=s(["\uc2e0\uc11d\uae30\uc2dc\ub300 \uc8fc\uac70\xb7\uacbd\uc81c \uc0dd\ud65c"],t.s)
B.app=new A.b("gen_kh_prehist_5","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300","\uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc8fc\uac70\xb7\uacbd\uc81c \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a9p,0,"\uc2e0\uc11d\uae30\uc2dc\ub300 \uc0ac\ub78c\ub4e4\uc740 \uac15\uac00\ub098 \ubc14\ub2f7\uac00\uc5d0 \uc6c0\uc9d1\uc744 \uc9d3\uace0 \uc815\ucc29 \uc0dd\ud65c\uc744 \ud558\uba70 \ub18d\uacbd\uacfc \ubaa9\ucd95\xb7\uc5b4\ub85c\ub97c \ubcd1\ud589\ud558\uc600\ub2e4. \uc6b0\uacbd \ubcf4\uae09\uacfc \ubcbc\ub18d\uc0ac \ud655\ub300, \ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc740 \ud6e8\uc52c \ud6c4\ub300(\ucca0\uae30~\uc0bc\uad6d\uc2dc\ub300 \uc774\ud6c4)\uc758 \uc77c\uc774\ub2e4.",B.Ql,B.O5,null)
B.a3k=s(["\uace1\uc2dd\uc744 \uc800\uc7a5\xb7\uc870\ub9ac\ud558\uace0 \uc2e4\uc744 \ubf51\uc544 \uc637\uac10\uc744 \uc9dc\ub294 \ub4f1 \uc815\ucc29 \uc0dd\ud65c\uc774 \ubc1c\uc804\ud558\uc600\ub2e4","\uccad\ub3d9 \ubb34\uae30\ub97c \ud65c\uc6a9\ud55c \uc815\ubcf5 \uc804\uc7c1\uc73c\ub85c \uacc4\uae09 \ubd84\ud654\uac00 \ucd09\uc9c4\ub418\uc5c8\ub2e4","\ud55c\uacfc\uc758 \uad50\uc5ed\uc744 \ud1b5\ud574 \uba85\ub3c4\uc804 \ub4f1 \uc911\uad6d \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc \uac74\ub9bd\uc744 \ud1b5\ud574 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \uacfc\uc2dc\ud558\uc600\ub2e4","\ubd88\uad50\uc640 \uc720\uad50 \uc0ac\uc0c1\uc774 \uc218\uc6a9\ub418\uc5b4 \ud1b5\uce58 \uc774\ub150\uc73c\ub85c \ud65c\uc6a9\ub418\uc5c8\ub2e4"],t.s)
B.aiD=s(["\uace1\uc2dd\uc744 \uc800\uc7a5\xb7\uc870\ub9ac\ud558\uace0 \uc2e4\uc744 \ubf51\uc544 \uc637\uac10\uc744 \uc9dc\ub294 \ub4f1 \uc815\ucc29 \uc0dd\ud65c\uc774 \ubc1c\uc804\ud558\uc600\ub2e4"],t.s)
B.a0F=s(["\uc2e0\uc11d\uae30\uc2dc\ub300 \ub300\ud45c \uc720\ubb3c\uacfc \uc0dd\ud65c\uc0c1"],t.s)
B.atr=new A.b("gen_kh_prehist_6","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uad6c\uc11d\uae30\xb7\uc2e0\uc11d\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc744 \ud1b5\ud574 \uc54c \uc218 \uc788\ub294 \uc2dc\ub300\uc0c1\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?\n\n"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30, \uac00\ub77d\ubc14\ud034, \uac08\ub3cc\uacfc \uac08\ud310"',B.a3k,0,"\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30(\uc800\uc7a5\xb7\uc870\ub9ac), \uac00\ub77d\ubc14\ud034(\uc2e4 \ubf51\uae30), \uac08\ub3cc\uacfc \uac08\ud310(\uace1\uc2dd \uac00\uacf5)\uc740 \ubaa8\ub450 \uc2e0\uc11d\uae30\uc2dc\ub300\uc758 \uc815\ucc29 \uc0dd\ud65c\uacfc \ucd08\uae30 \ub18d\uacbd\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc720\ubb3c\uc774\ub2e4. \uccad\ub3d9 \ubb34\uae30\xb7\uacc4\uae09 \ubd84\ud654\xb7\uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30\uc2dc\ub300, \uc911\uad6d \ud654\ud3d0 \uc720\uc785\uc740 \ucca0\uae30\uc2dc\ub300, \ubd88\uad50\xb7\uc720\uad50 \uc218\uc6a9\uc740 \uc0bc\uad6d\uc2dc\ub300 \uc774\ud6c4\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aiD,B.a0F,null)
B.ajT=s(["\ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\ub2e4","\uc528\uc871\uc744 \ub2e8\uc704\ub85c \ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9\uccb4 \uc0dd\ud65c\uc774 \uc720\uc9c0\ub418\uc5c8\ub2e4","\uc911\uad6d \ud654\ud3d0\uc778 \ubc18\ub7c9\uc804\uacfc \uba85\ub3c4\uc804\uc774 \ud65c\ubc1c\ud788 \uc720\ud1b5\ub418\uc5c8\ub2e4","\ucca0\uc81c \ubb34\uae30\uac00 \ubcf4\uae09\ub418\uc5b4 \uc815\ubcf5 \uc804\uc7c1\uc774 \ubcf8\uaca9\ud654\ub418\uc5c8\ub2e4","\ud55c\uc790\uac00 \uc804\ub798\ub418\uc5b4 \uc9c0\ubc30\uce35\uc758 \ubb38\uc790 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4"],t.s)
B.a6Y=s(["\ub18d\uc5c5 \uc0dd\uc0b0\ub825\uc774 \ub298\uc5b4\ub098\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\ub2e4"],t.s)
B.Jv=s(["\uccad\ub3d9\uae30\uc2dc\ub300 \uc0ac\ud68c \ubcc0\ud654"],t.s)
B.aBa=new A.b("gen_kh_prehist_7","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300",'\ub2e4\uc74c \uc720\ubb3c\uc774 \ucc98\uc74c \ub4f1\uc7a5\ud55c \uc2dc\ub300\uc758 \uc0ac\ud68c \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ube44\ud30c\ud615 \ub3d9\uac80, \ubc18\ub2ec \ub3cc\uce7c, \ubbfc\ubb34\ub2ac \ud1a0\uae30"',B.ajT,0,"\ube44\ud30c\ud615 \ub3d9\uac80\xb7\ubc18\ub2ec \ub3cc\uce7c\xb7\ubbfc\ubb34\ub2ac \ud1a0\uae30\ub294 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ub300\ud45c \uc720\ubb3c\uc774\ub2e4. \uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\ub294 \ub18d\uc5c5 \uc0dd\uc0b0\ub825 \uc99d\ub300\ub85c \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \uc0dd\uae30\uba74\uc11c \uc0ac\uc720 \uc7ac\uc0b0 \uac1c\ub150\uacfc \uacc4\uae09\uc774 \ubc1c\uc0dd\ud558\uc600\uace0, \uc774\ub294 \uace0\uc778\ub3cc \ub4f1 \uc9c0\ubc30\uce35 \ubb34\ub364\uc744 \ud1b5\ud574\uc11c\ub3c4 \ud655\uc778\ub41c\ub2e4. \uc911\uad6d \ud654\ud3d0 \uc720\ud1b5\uacfc \ucca0\uc81c \ubb34\uae30 \ubcf4\uae09\uc740 \ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.a6Y,B.Jv,null)
B.acp=s(["\uc911\uad6d\uacfc\uc758 \uad50\uc5ed\uc73c\ub85c \uba85\ub3c4\uc804, \ubc18\ub7c9\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uad6d\ub0b4\uc5d0 \uc720\uc785\ub418\uc5c8\ub2e4","\uac00\ub77d\ubc14\ud034\ub97c \uc774\uc6a9\ud574 \ucc98\uc74c\uc73c\ub85c \uc637\uac10\uc744 \uc9dc\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uc774 \uc9c0\ubc30\uce35\uc758 \uc758\ub840 \ub3c4\uad6c\ub85c \ucc98\uc74c \uc0ac\uc6a9\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc774 \ucc98\uc74c \uac74\ub9bd\ub418\uc5b4 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \ub098\ud0c0\ub0b4\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c \ub4f1 \ub5c0\uc11d\uae30\uac00 \uc0ac\ub0e5\uc758 \uc8fc\ub41c \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ub418\uc5c8\ub2e4"],t.s)
B.aet=s(["\uc911\uad6d\uacfc\uc758 \uad50\uc5ed\uc73c\ub85c \uba85\ub3c4\uc804, \ubc18\ub7c9\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uad6d\ub0b4\uc5d0 \uc720\uc785\ub418\uc5c8\ub2e4"],t.s)
B.acb=s(["\ucca0\uae30\uc2dc\ub300\uc758 \ub300\uc678 \uad50\ub958"],t.s)
B.awS=new A.b("gen_kh_prehist_8","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\ucca0\uae30\uc2dc\ub300\uc758 \ubaa8\uc2b5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.acp,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba74\uc11c \uba85\ub3c4\uc804\xb7\ubc18\ub7c9\uc804 \ub4f1 \uc911\uad6d \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5b4 \ub2f9\uc2dc \uc911\uad6d\uacfc\uc758 \uad50\uc5ed \uad00\uacc4\ub97c \ubcf4\uc5ec\uc900\ub2e4. \uac00\ub77d\ubc14\ud034\ub294 \uc2e0\uc11d\uae30, \uac70\uce5c\ubb34\ub2ac \uac70\uc6b8\uacfc \uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30, \ub5c0\uc11d\uae30\ub294 \uad6c\uc11d\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aet,B.acb,null)
B.agu=s([u.iD,"\uc528\uc871 \uacf5\ub3d9\uccb4\uac00 \ud568\uaed8 \uc0ac\uc6a9\ud55c \ud3c9\ub4f1\ud55c \uacf5\ub3d9 \ubb34\ub364\uc774\ub2e4","\ubd88\uad50\uc758 \uc804\ub798\uc640 \ud568\uaed8 \ub9cc\ub4e4\uc5b4\uc9c0\uae30 \uc2dc\uc791\ud55c \ubb34\ub364 \uc591\uc2dd\uc774\ub2e4","\uc8fc\ub85c \uc774\ub3d9 \uc0dd\ud65c\uc744 \ud558\ub358 \uad6c\uc11d\uae30\uc778\ub4e4\uc774 \uc0ac\uc6a9\ud55c \uc784\uc2dc \ub9e4\uc7a5 \uc2dc\uc124\uc774\ub2e4","\uc911\uad6d\uc758 \uc601\ud5a5\uc744 \ubc1b\uc544 \uc0bc\uad6d\uc2dc\ub300\uc5d0 \ucc98\uc74c \ub4f1\uc7a5\ud55c \ubb34\ub364 \uc591\uc2dd\uc774\ub2e4"],t.s)
B.a9N=s([u.iD],t.s)
B.ah4=s(["\uace0\uc778\ub3cc\uc758 \uc5ed\uc0ac\uc801 \uc758\ubbf8"],t.s)
B.avz=new A.b("gen_kh_prehist_9","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300 \uace0\uc778\ub3cc\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.agu,0,"\uace0\uc778\ub3cc\uc740 \uac70\ub300\ud55c \ub36e\uac1c\ub3cc\uc744 \uc62e\uae30\uace0 \uc138\uc6b0\ub294 \ub370 \ub9ce\uc740 \ub178\ub3d9\ub825\uc774 \ud544\uc694\ud588\uae30 \ub54c\ubb38\uc5d0, \uc774\ub97c \uc8fc\ub3c4\ud560 \uc218 \uc788\uc5c8\ub358 \uc9c0\ubc30\uce35\uc758 \uad8c\ub825\uacfc \uccad\ub3d9\uae30\uc2dc\ub300 \uacc4\uae09 \uc0ac\ud68c\uc758 \uc131\ub9bd\uc744 \ubcf4\uc5ec\uc8fc\ub294 \ub300\ud45c\uc801 \uc720\uc801\uc774\ub2e4.",B.a9N,B.ah4,null)
B.ahj=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4","\ubf08\ubc14\ub298\uacfc \uac00\ub77d\ubc14\ud034\ub97c \uc774\uc6a9\ud574 \ucc98\uc74c\uc73c\ub85c \uc637\uac10\uc744 \uc9dc\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\ucca0\uc81c \ub18d\uae30\uad6c \ubcf4\uae09\uc73c\ub85c \uae4a\uc774\uac08\uc774\uac00 \uac00\ub2a5\ud574\uc838 \uc0dd\uc0b0\ub825\uc774 \uae09\uc99d\ud558\uc600\ub2e4","\uc6b0\uacbd\uc774 \ub110\ub9ac \ubcf4\uae09\ub418\uc5b4 \uc18c\ub97c \uc774\uc6a9\ud55c \ub18d\uc0ac\uac00 \uc77c\ubc18\ud654\ub418\uc5c8\ub2e4","\uc911\uad6d \ud654\ud3d0\ub97c \ub9e4\uac1c\ub85c \ud55c \uad50\uc5ed\uc774 \uacbd\uc81c\uc758 \uc911\uc2ec\uc744 \uc774\ub8e8\uc5c8\ub2e4"],t.s)
B.aa1=s(["\ubc18\ub2ec \ub3cc\uce7c\ub85c \ubcbc \uc774\uc0ad\uc744 \uc790\ub974\ub294 \ub4f1 \ubcbc\ub18d\uc0ac\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \ud655\uc0b0\ub418\uc5c8\ub2e4"],t.s)
B.aen=s(["\uccad\ub3d9\uae30\uc2dc\ub300 \ub18d\uacbd\uc758 \ubc1c\ub2ec"],t.s)
B.azn=new A.b("gen_kh_prehist_10","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc758 \uacbd\uc81c \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ahj,0,"\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\ub294 \ubc18\ub2ec \ub3cc\uce7c\uacfc \uac19\uc740 \ub18d\uae30\uad6c\ub97c \uc774\uc6a9\ud574 \ubcbc\ub18d\uc0ac\uac00 \ud655\uc0b0\ub418\uba70 \uc789\uc5ec \uc0dd\uc0b0\ubb3c\uc774 \ub298\uc5b4\ub0ac\ub2e4. \ubf08\ubc14\ub298\xb7\uac00\ub77d\ubc14\ud034\ub294 \uc2e0\uc11d\uae30, \ucca0\uc81c \ub18d\uae30\uad6c\xb7\uc6b0\uacbd \ubcf4\uae09\uc740 \ucca0\uae30\uc2dc\ub300 \uc774\ud6c4, \uc911\uad6d \ud654\ud3d0 \uad50\uc5ed\uc740 \ucca0\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.aa1,B.aen,null)
B.a3x=s([u.c8,"\ub5c0\uc11d\uae30 \uc911\uc2ec\uc758 \ub3c4\uad6c \uccb4\uacc4\uac00 \uac04\uc11d\uae30 \uc911\uc2ec\uc73c\ub85c \uc804\ud658\ub418\uc5c8\ub2e4","\ubb34\ub9ac\ub97c \uc774\ub8ec \uc774\ub3d9 \uc0dd\ud65c\uc5d0\uc11c \uc815\ucc29 \uc0dd\ud65c\ub85c \ucc98\uc74c \uc804\ud658\ub418\uc5c8\ub2e4","\uad70\uc7a5 \uad6d\uac00\uac00 \ucc98\uc74c\uc73c\ub85c \ub4f1\uc7a5\ud558\uc5ec \uacc4\uae09 \uc0ac\ud68c\uac00 \uc131\ub9bd\ub418\uc5c8\ub2e4","\ud1a0\ud14c\ubbf8\uc998\xb7\uc560\ub2c8\ubbf8\uc998 \ub4f1 \uc6d0\uc2dc \uc2e0\uc559\uc774 \ucc98\uc74c\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4"],t.s)
B.ahN=s([u.c8],t.s)
B.Rk=s(["\uccad\ub3d9\uae30 \ubb38\ud654\uc758 \ub3c5\uc790\uc801 \ubc1c\uc804"],t.s)
B.axN=new A.b("gen_kh_prehist_11","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300","\uccad\ub3d9\uae30\uc2dc\ub300\uc5d0\uc11c \ucca0\uae30\uc2dc\ub300\ub85c \ub118\uc5b4\uac00\uba70 \ub098\ud0c0\ub09c \ubcc0\ud654\ub85c \uc633\uc740 \uac83\uc740?",B.a3x,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \uc138\ud615 \ub3d9\uac80\uacfc \uac70\ud478\uc9d1(\uc794\ubb34\ub2ac \uac70\uc6b8 \ub4f1)\uc744 \ud1b5\ud574 \ub3c5\uc790\uc801\uc778 \uccad\ub3d9\uae30 \ubb38\ud654\uac00 \ub354\uc6b1 \ubc1c\uc804\ud558\ub294 \ud55c\ud3b8, \ucca0\uc81c \ubb34\uae30\xb7\ub18d\uae30\uad6c\uac00 \ubcf4\uae09\ub418\uc5c8\ub2e4. \ub5c0\uc11d\uae30\u2192\uac04\uc11d\uae30 \uc804\ud658\uc740 \uad6c\uc11d\uae30\u2192\uc2e0\uc11d\uae30, \uc815\ucc29 \uc0dd\ud65c \uc2dc\uc791\uc740 \uc2e0\uc11d\uae30, \uad70\uc7a5 \uad6d\uac00 \ub4f1\uc7a5\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ubcc0\ud654\uc774\ub2e4.",B.ahN,B.Rk,null)
B.a8m=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4","\uace0\uc778\ub3cc\uc774 \ucc98\uc74c\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc838 \uc9c0\ubc30\uce35\uc758 \uad8c\uc704\ub97c \uc0c1\uc9d5\ud558\uc600\ub2e4","\ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub97c \uc774\uc6a9\ud574 \uace1\uc2dd\uc744 \uc800\uc7a5\ud558\ub294 \uc0dd\ud65c\uc774 \uc2dc\uc791\ub418\uc5c8\ub2e4","\uc8fc\uba39\ub3c4\ub07c\ub97c \uc774\uc6a9\ud55c \uc0ac\ub0e5\uacfc \ucc44\uc9d1\uc774 \uacbd\uc81c\uc0dd\ud65c\uc758 \uc911\uc2ec\uc774\uc5c8\ub2e4","\ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac\uac00 \ucc98\uc74c \uc2dc\uc791\ub418\uc5c8\ub2e4"],t.s)
B.adK=s(["\uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba70 \ud55c\uc790\uc640 \ud654\ud3d0 \ub4f1 \uc120\uc9c4 \ubb38\ubb3c\uc774 \uc720\uc785\ub418\uc5c8\ub2e4"],t.s)
B.Uf=s(["\ucca0\uae30\uc2dc\ub300 \ubb34\ub364 \uc591\uc2dd\uacfc \ub300\uc678 \uad50\ub958"],t.s)
B.awG=new A.b("gen_kh_prehist_12","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uccad\ub3d9\uae30\xb7\ucca0\uae30\uc2dc\ub300",'\ub2e4\uc74c \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud55c \uc2dc\ub300\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\uacfc \ub3c5\ubb34\ub364\uc774 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0ac\ub2e4."',B.a8m,0,"\ucca0\uae30\uc2dc\ub300\uc5d0\ub294 \ub110\ubb34\ub364\xb7\ub3c5\ubb34\ub364 \ub4f1 \uc0c8\ub85c\uc6b4 \ubb34\ub364 \uc591\uc2dd\uc774 \ub4f1\uc7a5\ud558\ub294 \ud55c\ud3b8, \uc911\uad6d\uacfc\uc758 \uad50\ub958\uac00 \ud65c\ubc1c\ud574\uc9c0\uba74\uc11c \ud55c\uc790\uc640 \uba85\ub3c4\uc804 \ub4f1\uc758 \ud654\ud3d0\uac00 \uc720\uc785\ub418\uc5c8\ub2e4. \uace0\uc778\ub3cc\uc740 \uccad\ub3d9\uae30, \ube57\uc0b4\ubb34\ub2ac \ud1a0\uae30\ub294 \uc2e0\uc11d\uae30, \uc8fc\uba39\ub3c4\ub07c\ub294 \uad6c\uc11d\uae30, \ubc18\ub2ec \ub3cc\uce7c\uc744 \uc774\uc6a9\ud55c \ubcbc\ub18d\uc0ac \uc2dc\uc791\uc740 \uccad\ub3d9\uae30\uc2dc\ub300\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.adK,B.Uf,null)
B.Pc=s([u.bP,"\ubaa8\ub4e0 \ubc94\uc8c4\uc790\ub97c \uc2e0\ubd84\uc5d0 \uad00\uacc4\uc5c6\uc774 \ub3d9\uc77c\ud558\uac8c \ucc98\ubc8c\ud558\ub294 \ud3c9\ub4f1 \uc0ac\ud68c\uc758 \uc6d0\ub9ac\ub97c \ub2f4\uace0 \uc788\ub2e4","\ubd88\uad50\uc758 \uacc4\uc728\uc5d0 \ub530\ub77c \uc0b4\uc0dd\uacfc \ub3c4\ub451\uc9c8\uc744 \uc5c4\uaca9\ud788 \uae08\uc9c0\ud55c \uc885\uad50\uc801 \uaddc\ubc94\uc774\ub2e4","\uc911\uad6d \ud55c\ub098\ub77c\uc758 \uc728\ub839\uc744 \uadf8\ub300\ub85c \uc218\uc6a9\ud558\uc5ec \uc81c\uc815\ud55c \uc131\ubb38 \ubc95\uc804\uc774\ub2e4","\ud654\ubc31 \ud68c\uc758\uc758 \ub9cc\uc7a5\uc77c\uce58\uc81c\ub97c \uba85\ubb38\ud654\ud55c \ud569\uc758 \uaddc\ubc94\uc774\ub2e4"],t.s)
