B.atx=new A.b("gen_kh_prehist_24","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uc5ec\ub7ec \ub098\ub77c\uc758 \uc131\uc7a5","\uc0bc\ud55c\uc758 \uacbd\uc81c\xb7\uc0ac\ud68c \ubaa8\uc2b5\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ahx,0,"\uc0bc\ud55c \uc911 \ubcc0\ud55c \uc9c0\uc5ed\uc740 \ucca0\uc774 \ud48d\ubd80\ud558\uac8c \uc0dd\uc0b0\ub418\uc5b4 \ud654\ud3d0\ucc98\ub7fc \uc0ac\uc6a9\ub418\uc5c8\uc744 \ubfd0 \uc544\ub2c8\ub77c \ub099\ub791\uacfc \uc65c \ub4f1\uc5d0 \uc218\ucd9c\ub418\uc5c8\ub2e4. \uc0ac\ucd9c\ub3c4\ub294 \ubd80\uc5ec, \uc11c\uc625\uc81c\ub294 \uace0\uad6c\ub824, \ubbfc\uba70\ub290\ub9ac\uc81c\ub294 \uc625\uc800, \ub2e8\uad81\xb7\uacfc\ud558\ub9c8\xb7\ubc18\uc5b4\ud53c\ub294 \ub3d9\uc608\uc758 \ud2b9\uc9d5\uc774\ub2e4.",B.IS,B.Sr,null)
B.OS=s(["\uc655\uad8c\uc744 \uac15\ud654\ud558\uace0 \ud638\uc871 \uc138\ub825\uc744 \uacac\uc81c\ud558\uae30 \uc704\ud574 \ub178\ube44\uc548\uac80\ubc95\uc744 \uc2dc\ud589\ud558\uc600\ub2e4","12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ucc98\uc74c\uc73c\ub85c \ud30c\uacac\ud558\uc600\ub2e4","\uacfc\uac70\uc81c\ub97c \ucc98\uc74c \uc2e4\uc2dc\ud558\uc5ec \uc2e0\uc9c4 \uc778\uc0ac\ub97c \ub4f1\uc6a9\ud558\uc600\ub2e4","\uc804\uc2dc\uacfc \uc81c\ub3c4\ub97c \ub9c8\ub828\ud558\uc5ec \uad00\ub9ac\uc5d0\uac8c \ud1a0\uc9c0\ub97c \uc9c0\uae09\ud558\uc600\ub2e4","\uad6d\uc790\uac10\uc744 \uc815\ube44\ud558\uace0 \uc591\ud604\uace0\ub97c \uc124\uce58\ud558\uc600\ub2e4"],t.s)
B.a0i=s(["\uc655\uad8c\uc744 \uac15\ud654\ud558\uace0 \ud638\uc871 \uc138\ub825\uc744 \uacac\uc81c\ud558\uae30 \uc704\ud574 \ub178\ube44\uc548\uac80\ubc95\uc744 \uc2dc\ud589\ud558\uc600\ub2e4"],t.s)
B.ab1=s(["\uad11\uc885\uc758 \uc655\uad8c \uac15\ud654 \uc815\ucc45"],t.s)
B.ar8=new A.b("gen_kh_goryeo_1","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44",'(\uac00) \uc655\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"(\uac00)\uc740/\ub294 \u300c\uc815\uacc4\u300d\uc640 \u300c\uacc4\ubc31\ub8cc\uc11c\u300d\ub97c \uc9c0\uc5b4 \uad00\ub9ac\uac00 \uc9c0\ucf1c\uc57c \ud560 \uaddc\ubc94\uc744 \uc81c\uc2dc\ud558\uace0, \uc5b5\uc6b8\ud558\uac8c \ub178\ube44\uac00 \ub41c \uc790\ub97c \uc591\uc778\uc73c\ub85c \ud574\ubc29\ud558\ub294 \ub178\ube44\uc548\uac80\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4."',B.OS,0,"\u300c\uc815\uacc4\u300d\xb7\u300c\uacc4\ubc31\ub8cc\uc11c\u300d \uc800\uc220\uacfc \ub178\ube44\uc548\uac80\ubc95\uc740 \uace0\ub824 \uad11\uc885\uc758 \uc815\ucc45\uc774\ub2e4. \uad11\uc885\uc740 \ub178\ube44\uc548\uac80\ubc95\uc73c\ub85c \ud638\uc871\uc758 \uacbd\uc81c\uc801\xb7\uad70\uc0ac\uc801 \uae30\ubc18\uc744 \uc57d\ud654\uc2dc\ud0a4\uace0 \uc655\uad8c\uc744 \uac15\ud654\ud558\uc600\ub2e4. 12\ubaa9 \uc124\uce58\ub294 \uc131\uc885, \uacfc\uac70\uc81c \uc2e4\uc2dc\ub294 \uad11\uc885(\uc30d\uae30 \uac74\uc758) \uc774\ud6c4 \uc131\uc885 \ub300\uc5d0 \uccb4\uc81c\ub85c \uc815\ucc29, \uc804\uc2dc\uacfc\ub294 \uacbd\uc885, \uad6d\uc790\uac10\xb7\uc591\ud604\uace0 \uc815\ube44\ub294 \uc608\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.a0i,B.ab1,null)
B.aeZ=s(["\uc804\uad6d\uc5d0 12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ud30c\uacac\ud558\uc600\ub2e4","\ub178\ube44\uc548\uac80\ubc95\uc744 \uc2dc\ud589\ud558\uc5ec \ud638\uc871\uc758 \uc138\ub825\uc744 \uc57d\ud654\uc2dc\ucf30\ub2e4","\ub3c5\uc790\uc801 \uc5f0\ud638\uc778 \uad11\ub355\xb7\uc900\ud48d\uc744 \uc0ac\uc6a9\ud558\uc600\ub2e4","\uac15\ub3d9 6\uc8fc\ub97c \ud68d\ub4dd\ud558\uc5ec \uc601\ud1a0\ub97c \ud655\uc7a5\ud558\uc600\ub2e4","\ucc9c\ub9ac\uc7a5\uc131\uc744 \ucd95\uc870\ud558\uc5ec \uad6d\uacbd \ubc29\ube44\ub97c \uac15\ud654\ud558\uc600\ub2e4"],t.s)
B.a9Z=s(["\uc804\uad6d\uc5d0 12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ud30c\uacac\ud558\uc600\ub2e4"],t.s)
B.J3=s(["\uc131\uc885\uc758 \uc720\uad50\uc801 \ud1b5\uce58\uccb4\uc81c \uc815\ube44"],t.s)
B.aqs=new A.b("gen_kh_goryeo_2","korean_history","\uace0\ub824","\ud6c4\uc0bc\uad6d \ud1b5\uc77c\uacfc \ud1b5\uce58\uccb4\uc81c \uc815\ube44",'\ub2e4\uc74c \uac74\uc758\ub97c \ubc1b\uc544\ub4e4\uc778 \uc655\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\ucd5c\uc2b9\ub85c\uac00 \uc2dc\ubb34 28\uc870\ub97c \uc62c\ub824, \ubd88\uad50 \ud589\uc0ac\ub97c \uc904\uc774\uace0 \uc720\uad50 \uc815\uce58 \uc774\ub150\uc5d0 \ub530\ub77c \ud1b5\uce58 \uccb4\uc81c\ub97c \uc815\ube44\ud560 \uac83\uc744 \uac74\uc758\ud558\uc600\ub2e4."',B.aeZ,0,"\ucd5c\uc2b9\ub85c\uc758 \uc2dc\ubb34 28\uc870\ub97c \ubc1b\uc544\ub4e4\uc778 \uc655\uc740 \uc131\uc885\uc774\ub2e4. \uc131\uc885\uc740 \uc720\uad50 \uc815\uce58 \uc774\ub150\uc5d0 \ub530\ub77c \uc804\uad6d\uc5d0 12\ubaa9\uc744 \uc124\uce58\ud558\uace0 \uc9c0\ubc29\uad00\uc744 \ucc98\uc74c \ud30c\uacac\ud558\ub294 \ub4f1 \uc911\uc559 \uc9d1\uad8c \uccb4\uc81c\ub97c \uc815\ube44\ud558\uc600\ub2e4. \ub178\ube44\uc548\uac80\ubc95\xb7\ub3c5\uc790 \uc5f0\ud638 \uc0ac\uc6a9\uc740 \uad11\uc885, \uac15\ub3d9 6\uc8fc \ud68d\ub4dd\uc740 \uc11c\ud76c\uc758 \uc678\uad50 \ub2f4\ud310(\uc131\uc885 \ub300\uc774\ub098 \ubcc4\ub3c4 \ub300\uc678\uad00\uacc4 \uc0ac\uac74), \ucc9c\ub9ac\uc7a5\uc131 \ucd95\uc870\ub294 \uc815\uc885~\ub355\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.a9Z,B.J3,null)
B.Tf=s([u.W,"\uc758\uc815\ubd80\uc640 6\uc870\ub97c \uc911\uc2ec\uc73c\ub85c \ud55c \ud1b5\uce58 \uccb4\uc81c\ub97c \uac16\ucd94\uc5c8\ub2e4","3\uc131 6\ubd80 \uccb4\uc81c\ub97c \uac16\ucd94\uc5b4 \uc0c1\uc11c\uc131\uc774 \uc2e4\uc9c8\uc801 \uc815\ucc45\uc744 \uacb0\uc815\ud558\uc600\ub2e4","\ube44\ubcc0\uc0ac\uac00 \uad6d\uc815 \uc804\ubc18\uc744 \ucd1d\uad04\ud558\ub294 \ucd5c\uace0 \uae30\uad6c\uc600\ub2e4","\ub3c5\uc11c\uc0bc\ud488\uacfc\ub97c \uc2e4\uc2dc\ud558\uc5ec \uad00\ub9ac\ub97c \uc120\ubc1c\ud558\uc600\ub2e4"],t.s)
B.MX=s([u.W],t.s)
