B.as5=new A.b("gen_kh_goryeo_14","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)",'(\uac00) \uc804\ud22c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uac15\uac10\ucc2c\uc774 \uc774\ub044\ub294 \uace0\ub824\uad70\uc774 \uadc0\uc8fc\uc5d0\uc11c \uac70\ub780\uc758 \uc18c\ubc30\uc555\uc774 \uc774\ub044\ub294 \ub300\uad70\uc744 \ud06c\uac8c \uaca9\ud30c\ud558\uc600\ub2e4."',B.a0z,0,"\uadc0\uc8fc \ub300\ucca9\uc740 \uac15\uac10\ucc2c\uc774 \uac70\ub780\uc758 3\ucc28 \uce68\uc785(\uc18c\ubc30\uc555\uc758 \ub300\uad70)\uc744 \ud06c\uac8c \uaca9\ud30c\ud55c \uc804\ud22c\ub85c, \uc774\ud6c4 \uace0\ub824\xb7\uac70\ub780\xb7\uc1a1 \uc0ac\uc774\uc5d0 \uc138\ub825 \uade0\ud615\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4. \ubcc4\ubb34\ubc18\uc758 \uc5ec\uc9c4 \uc815\ubc8c, \ucc98\uc778\uc131 \uc804\ud22c(\ubabd\uace8), \ud64d\uc0b0 \ub300\ucca9(\uc65c\uad6c), \uc704\ud654\ub3c4 \ud68c\uad70(\uace0\ub824 \ub9d0)\uacfc\ub294 \uad6c\ubd84\ub41c\ub2e4.",B.a5v,B.ah0,null)
B.Nu=s(["\ubcc4\ubb34\ubc18\uc744 \uc774\ub04c\uace0 \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud55c \ub4a4 \ub3d9\ubd81 9\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4","\uac15\ub3d9 6\uc8fc\ub97c \ud68d\ub4dd\ud558\uc5ec \uc555\ub85d\uac15 \uc720\uc5ed\uc744 \ud655\ubcf4\ud558\uc600\ub2e4","\uac15\ud654\ub3c4\ub85c \ucc9c\ub3c4\ud558\uc5ec \ubabd\uace8\uc5d0 \ud56d\uc804\ud558\uc600\ub2e4","\uadc0\uc8fc\uc5d0\uc11c \uac70\ub780\uc758 \ub300\uad70\uc744 \uaca9\ud30c\ud558\uc600\ub2e4","\uc4f0\uc2dc\ub9c8\uc12c(\ub300\ub9c8\ub3c4)\uc744 \uc815\ubc8c\ud558\uc5ec \uc65c\uad6c\ub97c \ud1a0\ubc8c\ud558\uc600\ub2e4"],t.s)
B.a1z=s(["\ubcc4\ubb34\ubc18\uc744 \uc774\ub04c\uace0 \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud55c \ub4a4 \ub3d9\ubd81 9\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4"],t.s)
B.TE=s(["\uc724\uad00\uc758 \uc5ec\uc9c4 \uc815\ubc8c\uacfc \ub3d9\ubd81 9\uc131"],t.s)
B.aqD=new A.b("gen_kh_goryeo_15","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)","\uc724\uad00\uc758 \uc5ec\uc9c4 \uc815\ubc8c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Nu,0,"\uc724\uad00\uc740 \uae30\ubcd1 \uc911\uc2ec\uc758 \ubcc4\ubb34\ubc18\uc744 \ud3b8\uc131\ud558\uc5ec \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud558\uace0 \ub3d9\ubd81 9\uc131\uc744 \uc313\uc544 \uacbd\uacc4\ub97c \uc0bc\uc558\uc73c\ub098, \ubc29\uc5b4\uc758 \uc5b4\ub824\uc6c0\uc73c\ub85c \uc5bc\ub9c8 \ub4a4 \uc5ec\uc9c4\uc5d0\uac8c \ub418\ub3cc\ub824\uc8fc\uc5c8\ub2e4. \uac15\ub3d9 6\uc8fc \ud68d\ub4dd\uc740 \uc11c\ud76c, \uac15\ud654\ub3c4 \ucc9c\ub3c4\ub294 \ubabd\uace8 \uce68\uc785\uae30, \uadc0\uc8fc \ub300\ucca9\uc740 \uac15\uac10\ucc2c, \uc4f0\uc2dc\ub9c8 \uc815\ubc8c\uc740 \uace0\ub824 \ub9d0~\uc870\uc120 \ucd08\uc758 \uc77c\uc774\ub2e4.",B.a1z,B.TE,null)
B.Z9=s(["\uac15\ud654\ub3c4\ub85c \ub3c4\uc74d\uc744 \uc62e\uae30\uace0 \uc7a5\uae30 \ud56d\uc804\uc744 \uc900\ube44\ud558\uc600\ub2e4","\uc11c\ud76c\uac00 \uc18c\uc190\ub155\uacfc \ub2f4\ud310\ud558\uc5ec \uac15\ub3d9 6\uc8fc\ub97c \ud655\ubcf4\ud558\uc600\ub2e4","\ubcc4\ubb34\ubc18\uc744 \ud3b8\uc131\ud558\uc5ec \ub3d9\ubd81 9\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4","\uac15\uac10\ucc2c\uc774 \uadc0\uc8fc\uc5d0\uc11c \uc801\uc758 \ub300\uad70\uc744 \uaca9\ud30c\ud558\uc600\ub2e4","4\uad70 6\uc9c4\uc744 \uac1c\ucc99\ud558\uc5ec \uad6d\uacbd\uc744 \ud655\uc815\ud558\uc600\ub2e4"],t.s)
B.a5f=s(["\uac15\ud654\ub3c4\ub85c \ub3c4\uc74d\uc744 \uc62e\uae30\uace0 \uc7a5\uae30 \ud56d\uc804\uc744 \uc900\ube44\ud558\uc600\ub2e4"],t.s)
