B.avX=new A.b("gen_kh_goryeo_16","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)","\ubabd\uace8\uc758 \uce68\uc785\uc5d0 \ub300\ud55c \uace0\ub824\uc758 \ub300\uc751\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Z9,0,"\ubabd\uace8\uc758 \uc787\ub2e8 \uce68\uc785\uc5d0 \ucd5c\uc528 \ubb34\uc2e0 \uc815\uad8c\uc740 \uac15\ud654\ub3c4\ub85c \ub3c4\uc74d\uc744 \uc62e\uae30\uace0 \uc7a5\uae30 \ud56d\uc804\uc744 \uc900\ube44\ud558\uc600\ub2e4. \uc774 \uacfc\uc815\uc5d0\uc11c \ucc98\uc778\uc131 \uc804\ud22c(\uae40\uc724\ud6c4, \uc0b4\ub9ac\ud0c0 \uc0ac\uc0b4), \ud314\ub9cc\ub300\uc7a5\uacbd \uc870\ud310 \ub4f1\uc774 \uc774\ub8e8\uc5b4\uc84c\ub2e4. \uc11c\ud76c\uc758 \ub2f4\ud310\xb7\ubcc4\ubb34\ubc18\uacfc \ub3d9\ubd81 9\uc131\xb7\uac15\uac10\ucc2c\uc758 \uadc0\uc8fc \ub300\ucca9\uc740 \uac01\uac01 \uac70\ub780\xb7\uc5ec\uc9c4\uacfc \uad00\ub828\ub41c \uc0ac\uac74\uc774\uba70, 4\uad70 6\uc9c4 \uac1c\ucc99\uc740 \uc870\uc120 \uc138\uc885 \ub300\uc758 \uc77c\uc774\ub2e4.",B.a5f,B.abv,null)
B.a7B=s(["\uc815\ub3d9\ud589\uc131\uc774 \uc124\uce58\ub418\uace0 \uace0\ub824\uc758 \uc655\uc774 \uc6d0\uc758 \uacf5\uc8fc\uc640 \ud63c\uc778\ud558\ub294 \uad00\ud589\uc774 \uc774\uc5b4\uc84c\ub2e4","\uac15\ud654\ub3c4\ub85c \ucc9c\ub3c4\ud558\uc5ec \ubabd\uace8\uc5d0 \ud56d\uc804\ud558\uc600\ub2e4","\uc11c\ud76c\uac00 \uac70\ub780\uacfc \ub2f4\ud310\ud558\uc5ec \uac15\ub3d9 6\uc8fc\ub97c \ud68d\ub4dd\ud558\uc600\ub2e4","\uc0bc\ubcc4\ucd08\uac00 \uc9c4\ub3c4\ub85c \uadfc\uac70\uc9c0\ub97c \uc62e\uaca8 \ud56d\uc7c1\ud558\uc600\ub2e4","\uc724\uad00\uc774 \ubcc4\ubb34\ubc18\uc744 \uc774\ub04c\uace0 \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud558\uc600\ub2e4"],t.s)
