B.aBG=new A.b("gen_kh_goryeo_22","korean_history","\uace0\ub824","\uacbd\uc81c\xb7\uc0ac\ud68c\xb7\ubb38\ud654","\uace0\ub824\uc758 \uc778\uc1c4 \ubb38\ud654\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.W_,0,"\uccad\uc8fc \ud765\ub355\uc0ac\uc5d0\uc11c \uac04\ud589\ub41c \u300c\uc9c1\uc9c0\uc2ec\uccb4\uc694\uc808\u300d(\ubc31\uc6b4 \ud654\uc0c1)\uc740 \ud604\uc874\ud558\ub294 \uc138\uacc4\uc5d0\uc11c \uac00\uc7a5 \uc624\ub798\ub41c \uae08\uc18d \ud65c\uc790 \uc778\uc1c4\ubcf8\uc73c\ub85c \uacf5\uc778\ubc1b\uc558\ub2e4. \u300c\ud314\ub9cc\ub300\uc7a5\uacbd\u300d\uc740 \ubaa9\ud310 \uc778\uc1c4\ubb3c, \u300c\ubb34\uad6c\uc815\uad11\ub300\ub2e4\ub77c\ub2c8\uacbd\u300d\uc740 \ud1b5\uc77c\uc2e0\ub77c, \u300c\ub3d9\uc758\ubcf4\uac10\u300d\uacfc \u300c\uacbd\uad6d\ub300\uc804\u300d\uc740 \uc870\uc120 \uc2dc\ub300\uc758 \uc11c\uc801\uc774\ub2e4.",B.H4,B.aj1,null)
B.a6Q=s(["\uace0\ub824\ub294 \uc0c1\uac10 \uae30\ubc95\uc744 \ub3c5\uc790\uc801\uc73c\ub85c \ubc1c\uc804\uc2dc\ucf1c \uc0c1\uac10\uccad\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub0c8\ub2e4","\ubd84\uccad\uc0ac\uae30\uac00 \uace0\ub824 \uc804\uae30\uc758 \ub300\ud45c\uc801\uc778 \ub3c4\uc790\uae30 \uc591\uc2dd\uc774\uc5c8\ub2e4","\ubc31\uc790\uac00 \uace0\ub824 \uc2dc\ub300 \uc804\ubc18\uc5d0 \uac78\uccd0 \uac00\uc7a5 \ub9ce\uc774 \uc81c\uc791\ub418\uc5c8\ub2e4","\uccad\uc790\ub294 \uc870\uc120 \uc2dc\ub300\uc5d0 \ub4e4\uc5b4\uc640 \ucc98\uc74c \uc81c\uc791\ub418\uae30 \uc2dc\uc791\ud558\uc600\ub2e4","\uace0\ub824\uccad\uc790\ub294 \uc65c\ub780 \uc774\ud6c4 \uc77c\ubcf8\uc758 \uae30\uc220\uc744 \ubc1b\uc544\ub4e4\uc5ec \ub9cc\ub4e4\uc5b4\uc84c\ub2e4"],t.s)
