B.aAC=new A.b("gen_kh_goryeo_23","korean_history","\uace0\ub824","\uacbd\uc81c\xb7\uc0ac\ud68c\xb7\ubb38\ud654","\uace0\ub824\uccad\uc790\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6Q,0,"\uace0\ub824\ub294 \uc911\uad6d\uc758 \uc790\uae30 \uae30\uc220\uc744 \ubc1b\uc544\ub4e4\uc774\uba74\uc11c\ub3c4 \uc0c1\uac10 \uae30\ubc95\uc744 \ub3c5\uc790\uc801\uc73c\ub85c \ubc1c\uc804\uc2dc\ucf1c \ubb34\ub2ac\ub97c \uc0c8\uaca8 \ub123\uc740 \uc0c1\uac10\uccad\uc790\ub97c \ub9cc\ub4e4\uc5b4 \ub0c8\uc73c\uba70, \uc774\ub294 \uace0\ub824 \ub3c4\uc790 \ubb38\ud654\uc758 \ub3c5\ucc3d\uc131\uc744 \ubcf4\uc5ec \uc900\ub2e4. \ubd84\uccad\uc0ac\uae30\xb7\ubc31\uc790\ub294 \uc870\uc120 \uc2dc\ub300\uc5d0 \uc720\ud589\ud55c \ub3c4\uc790\uae30 \uc591\uc2dd\uc774\ub2e4.",B.a8G,B.afx,null)
B.a1q=s([u.tL,"\uac70\ub780\uc758 \uce68\uc785\uc744 \ubb3c\ub9ac\uce5c \uac83\uc744 \uae30\ub150\ud558\uc5ec \uc870\ud310\ud55c \ub300\uc7a5\uacbd\uc774\ub2e4","\uae08\uc18d \ud65c\uc790\ub85c \uc778\uc1c4\ub41c \uc138\uacc4 \ucd5c\ucd08\uc758 \ubd88\uacbd\uc774\ub2e4","\uc870\uc120 \ud0dc\uc870 \ub300\uc5d0 \uc0c8\ub85c \uc870\ud310\ub418\uc5b4 \ud574\uc778\uc0ac\uc5d0 \ubcf4\uad00\ub418\uc5c8\ub2e4","\uc784\uc9c4\uc65c\ub780 \ub54c \uc18c\uc2e4\ub418\uc5b4 \ud604\uc7ac\ub294 \uc804\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
