B.aBM=new A.b("gen_kh_js1_2","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc138\uc885 \ub300\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.VD,0,"\uc138\uc885\uc740 \uc9d1\ud604\uc804\uc744 \uc124\uce58\ud558\uc5ec \ud559\uc790\ub97c \uc591\uc131\ud558\uace0 \ud6c8\ubbfc\uc815\uc74c\uc744 \ucc3d\uc81c\xb7\ubc18\ud3ec\ud558\ub294 \ud55c\ud3b8, 4\uad70 6\uc9c4 \uac1c\ucc99, \uce21\uc6b0\uae30\xb7\uc559\ubd80\uc77c\uad6c \ub4f1 \uacfc\ud559 \uae30\uad6c \uc81c\uc791, \ub300\ub9c8\ub3c4 \uc815\ubc8c(\uc774\uc885\ubb34) \ub4f1 \ub2e4\uc591\ud55c \uc5c5\uc801\uc744 \ub0a8\uacbc\ub2e4. 6\uc870 \uc9c1\uacc4\uc81c \uc2dc\ud589\uc740 \ud0dc\uc885, \u300c\uacbd\uad6d\ub300\uc804\u300d \uc644\uc131\uc740 \uc131\uc885, \uc704\ud654\ub3c4 \ud68c\uad70\uc740 \uc774\uc131\uacc4(\uace0\ub824 \ub9d0), \uc9c1\uc804\ubc95\uc740 \uc138\uc870 \ub300\uc758 \uc77c\uc774\ub2e4.",B.akS,B.S5,null)
B.Vn=s(["\ucd5c\uc724\ub355\uacfc \uae40\uc885\uc11c\ub97c \ubcf4\ub0b4 \uc555\ub85d\uac15\uacfc \ub450\ub9cc\uac15 \uc720\uc5ed\uc5d0 4\uad70\uacfc 6\uc9c4\uc744 \uc124\uce58\ud558\uc600\ub2e4","\uc724\uad00\uc744 \ubcf4\ub0b4 \uc5ec\uc9c4\uc744 \uc815\ubc8c\ud558\uace0 \ub3d9\ubd81 9\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4","\uc774\uc885\ubb34\ub97c \ubcf4\ub0b4 \uc4f0\uc2dc\ub9c8\uc12c(\ub300\ub9c8\ub3c4)\uc744 \uc815\ubc8c\ud558\uc600\ub2e4","\ucc99\uacc4\uad11\uc758 \uc808\uac15\ubcd1\ubc95\uc744 \ub3c4\uc785\ud558\uc5ec \uc65c\uad6c\uc5d0 \ub300\ube44\ud558\uc600\ub2e4","\uc774\uc21c\uc2e0\uc774 \ud55c\uc0b0\ub3c4\uc5d0\uc11c \ud559\uc775\uc9c4 \uc804\ubc95\uc73c\ub85c \uc65c\uad70\uc744 \uaca9\ud30c\ud558\uc600\ub2e4"],t.s)
B.QK=s(["\ucd5c\uc724\ub355\uacfc \uae40\uc885\uc11c\ub97c \ubcf4\ub0b4 \uc555\ub85d\uac15\uacfc \ub450\ub9cc\uac15 \uc720\uc5ed\uc5d0 4\uad70\uacfc 6\uc9c4\uc744 \uc124\uce58\ud558\uc600\ub2e4"],t.s)
