B.atS=new A.b("gen_kh_js1_3","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc138\uc885 \ub300\uc5d0 \uac1c\ucc99\ud55c \uad6d\uacbd \uc9c0\uc5ed\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Vn,0,"\uc138\uc885\uc740 \ucd5c\uc724\ub355(4\uad70)\uacfc \uae40\uc885\uc11c(6\uc9c4)\ub97c \ubcf4\ub0b4 \uc555\ub85d\uac15\xb7\ub450\ub9cc\uac15 \uc720\uc5ed\uc5d0 4\uad70 6\uc9c4\uc744 \uac1c\ucc99\ud558\uc5ec \uc624\ub298\ub0a0\uacfc \ube44\uc2b7\ud55c \uad6d\uacbd\uc120\uc744 \ud655\uc815\ud558\uc600\ub2e4. \ub3d9\ubd81 9\uc131 \ucd95\uc870\ub294 \uace0\ub824 \uc724\uad00, \ub300\ub9c8\ub3c4 \uc815\ubc8c\uc740 \uc138\uc885 \ub300 \uc774\uc885\ubb34(\ubcc4\uac1c \uc0ac\uac74), \uc808\uac15\ubcd1\ubc95 \ub3c4\uc785\uacfc \uc774\uc21c\uc2e0\uc758 \ud65c\uc57d\uc740 \uc784\uc9c4\uc65c\ub780 \uad00\ub828 \uc0ac\uc2e4\uc774\ub2e4.",B.QK,B.aiA,null)
B.a27=s([u.pE,"\uc655\uac74\uc774 \ud6c4\uc0bc\uad6d\uc744 \ud1b5\uc77c\ud558\uace0 \uac1c\uacbd\uc5d0 \ub3c4\uc74d\ud558\uc600\ub2e4","\uacf5\ubbfc\uc655\uc774 \ubc18\uc6d0 \uc790\uc8fc \uac1c\ud601\uc744 \ucd94\uc9c4\ud558\uba70 \ub3c4\uc74d\uc744 \uc62e\uacbc\ub2e4","\uacac\ud6e4\uc774 \uc644\uc0b0\uc8fc(\uc804\uc8fc)\uc5d0 \ub3c4\uc74d\ud558\uc5ec \ud6c4\ubc31\uc81c\ub97c \uac74\uad6d\ud558\uc600\ub2e4","\uad81\uc608\uac00 \ucca0\uc6d0\uc5d0 \ub3c4\uc74d\ud558\uc5ec \ud6c4\uace0\uad6c\ub824(\ud0dc\ubd09)\ub97c \uac74\uad6d\ud558\uc600\ub2e4"],t.s)
B.IG=s([u.pE],t.s)
B.aeo=s(["\uc870\uc120\uc758 \uac74\uad6d \uacfc\uc815"],t.s)
B.azY=new A.b("gen_kh_js1_4","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc870\uc120\uc758 \uac74\uad6d\uacfc \ud55c\uc591 \ucc9c\ub3c4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a27,0,"\uc774\uc131\uacc4\ub294 \uc704\ud654\ub3c4 \ud68c\uad70(1388)\uc73c\ub85c \uc815\uad8c\uc744 \uc7a5\uc545\ud55c \ub4a4 \uc815\ub3c4\uc804 \ub4f1 \uc2e0\uc9c4 \uc0ac\ub300\ubd80\uc640 \ud568\uaed8 \uc870\uc120\uc744 \uac74\uad6d(1392)\ud558\uace0, \ud55c\uc591\uc73c\ub85c \ub3c4\uc74d\uc744 \uc62e\uaca8 \uacbd\ubcf5\uad81 \ub4f1\uc744 \uc138\uc6b0\uace0 \ud1b5\uce58 \uae30\ubc18\uc744 \ub9c8\ub828\ud558\uc600\ub2e4. \ub098\uba38\uc9c0 \uc120\ud0dd\uc9c0\ub294 \uace0\ub824 \uac74\uad6d \uc804\ud6c4 \ud6c4\uc0bc\uad6d \uc2dc\uae30 \ub610\ub294 \uace0\ub824 \ud6c4\uae30\uc758 \uc0ac\uc2e4\uc774\ub2e4.",B.IG,B.aeo,null)
B.IN=s(["\uce21\uc6b0\uae30, \uc559\ubd80\uc77c\uad6c, \uc790\uaca9\ub8e8 \ub4f1\uc744 \uc81c\uc791\ud558\uc5ec \ub18d\uc5c5\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \ud65c\uc6a9\ud558\uc600\ub2e4","\u300c\uc9c1\uc9c0\uc2ec\uccb4\uc694\uc808\u300d\uc744 \uae08\uc18d \ud65c\uc790\ub85c \uc778\uc1c4\ud558\uc600\ub2e4","\uac70\uc911\uae30\ub97c \uc774\uc6a9\ud558\uc5ec \uc218\uc6d0 \ud654\uc131\uc744 \ucd95\uc870\ud558\uc600\ub2e4","\u300c\ub3d9\uc758\ubcf4\uac10\u300d\uc744 \ud3b8\ucc2c\ud558\uc5ec \uc758\ud559 \ubc1c\uc804\uc5d0 \uae30\uc5ec\ud558\uc600\ub2e4","\u300c\uace4\uc5ec\ub9cc\uad6d\uc804\ub3c4\u300d\ub97c \ub4e4\uc5ec\uc640 \uc138\uacc4 \uc9c0\ub9ac \uc778\uc2dd\uc744 \ub113\ud614\ub2e4"],t.s)
B.a75=s(["\uce21\uc6b0\uae30, \uc559\ubd80\uc77c\uad6c, \uc790\uaca9\ub8e8 \ub4f1\uc744 \uc81c\uc791\ud558\uc5ec \ub18d\uc5c5\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \ud65c\uc6a9\ud558\uc600\ub2e4"],t.s)
B.a8D=s(["\uc138\uc885 \ub300 \uacfc\ud559 \uae30\uc220"],t.s)
B.ayn=new A.b("gen_kh_js1_5","korean_history","\uc870\uc120\uc804\uae30","\uad6d\uac00 \uae30\ud2c0 \ub9c8\ub828(\ud0dc\uc870~\uc138\uc885)","\uc138\uc885 \ub300\uc758 \uacfc\ud559 \uae30\uc220 \ubc1c\ub2ec\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.IN,0,"\uc138\uc885 \ub300\uc5d0\ub294 \uac15\uc6b0\ub7c9\uc744 \uce21\uc815\ud558\ub294 \uce21\uc6b0\uae30, \ud574\uc2dc\uacc4\uc778 \uc559\ubd80\uc77c\uad6c, \ubb3c\uc2dc\uacc4\uc778 \uc790\uaca9\ub8e8 \ub4f1\uc774 \uc81c\uc791\ub418\uc5b4 \ub18d\uc5c5 \uc0dd\uc0b0\uacfc \uc2dc\uac04 \uce21\uc815\uc5d0 \uc2e4\uc9c8\uc801\uc73c\ub85c \ud65c\uc6a9\ub418\uc5c8\ub2e4. \u300c\uc9c1\uc9c0\uc2ec\uccb4\uc694\uc808\u300d\uc740 \uace0\ub824, \uac70\uc911\uae30\uc640 \uc218\uc6d0 \ud654\uc131\uc740 \uc815\uc870, \u300c\ub3d9\uc758\ubcf4\uac10\u300d\uc740 \uad11\ud574\uad70 \ub300, \u300c\uace4\uc5ec\ub9cc\uad6d\uc804\ub3c4\u300d \uc804\ub798\ub294 \uc870\uc120 \ud6c4\uae30\uc758 \uc77c\uc774\ub2e4.",B.a75,B.a8D,null)
B.a6j=s([u.hJ,"\uc124\ucd1d\uc774 \ud55c\uc790\uc758 \uc74c\uacfc \ub73b\uc744 \ube4c\ub824 \uc774\ub450\ub97c \uc815\ub9ac\ud558\uc600\ub2e4","\uc8fc\uc2dc\uacbd\uc774 \uad6d\ubb38 \uc5f0\uad6c\uc18c\ub97c \uc138\uc6cc \ud55c\uae00\uc744 \uccb4\uacc4\uc801\uc73c\ub85c \uc815\ub9ac\ud558\uc600\ub2e4","\uace0\ub824 \uad11\uc885\uc774 \uacfc\uac70\uc81c \uc2e4\uc2dc\uc640 \ud568\uaed8 \uc0c8\ub85c\uc6b4 \ubb38\uc790\ub97c \ubc18\ud3ec\ud558\uc600\ub2e4","\uac11\uc624\uac1c\ud601 \ub54c \uacf5\ubb38\uc11c\uc5d0 \ucc98\uc74c\uc73c\ub85c \ud55c\uae00\uc744 \uc0ac\uc6a9\ud558\ub3c4\ub85d \ud558\uc600\ub2e4"],t.s)
