B.aw8=new A.b("gen_kh_js1_14","korean_history","\uc870\uc120\uc804\uae30","\uc0ac\ub9bc\uc758 \uc131\uc7a5\uacfc \uc0ac\ud654\xb7\ubd95\ub2f9",'\ub2e4\uc74c \uc0ac\uac74\uc5d0 \ud574\ub2f9\ud558\ub294 \uc0ac\ud654\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uae40\uc885\uc9c1\uc758 \u300c\uc870\uc758\uc81c\ubb38\u300d\uc774 \ube4c\ubbf8\uac00 \ub418\uc5b4, \ud6c8\uad6c \uc138\ub825\uc774 \uc0ac\ub9bc\uc744 \ucd95\ucd9c\ud558\uace0 \ud070 \ud654\ub97c \uc785\ud614\ub2e4."',B.ZE,0,"\uc5f0\uc0b0\uad70 \ub300\uc5d0 \uae40\uc885\uc9c1\uc758 \u300c\uc870\uc758\uc81c\ubb38\u300d\uc774 \ubb38\uc81c\uac00 \ub418\uc5b4 \uc0ac\ub9bc\uc774 \ud654\ub97c \uc785\uc740 \uc0ac\uac74\uc740 \ubb34\uc624\uc0ac\ud654(1498)\uc774\ub2e4. \uac11\uc790\uc0ac\ud654\ub294 \uc5f0\uc0b0\uad70\uc758 \uc0dd\ubaa8 \ud3d0\ube44 \uc0ac\uac74\uc774 \ubc1c\ub2e8, \uae30\ubb18\uc0ac\ud654\ub294 \uc870\uad11\uc870\uc758 \uac1c\ud601\uc5d0 \ub300\ud55c \ud6c8\uad6c\uc758 \ubc18\ubc1c, \uc744\uc0ac\uc0ac\ud654\ub294 \uc678\ucc99 \uac04\uc758 \ub300\ub9bd\uc774 \uc6d0\uc778\uc774\uc5c8\ub2e4.",B.a6X,B.Nb,null)
B.aa8=s(["\ud604\ub7c9\uacfc \uc2e4\uc2dc\uc640 \uc704\ud6c8 \uc0ad\uc81c \ub4f1\uc744 \ucd94\uc9c4\ud558\ub2e4 \ud6c8\uad6c\uc758 \ubc18\ubc1c\ub85c \uae30\ubb18\uc0ac\ud654\ub97c \ub9de\uc558\ub2e4","\u300c\uacbd\uad6d\ub300\uc804\u300d\uc744 \uc644\uc131\ud558\uc5ec \ud1b5\uce58 \uaddc\ubc94\uc744 \ud655\ub9bd\ud558\uc600\ub2e4","6\uc870 \uc9c1\uacc4\uc81c\ub97c \uc2dc\ud589\ud558\uc5ec \uc655\uad8c\uc744 \uac15\ud654\ud558\uc600\ub2e4","\ud0d5\ud3c9\ucc45\uc744 \uc2e4\uc2dc\ud558\uc5ec \ubd95\ub2f9 \uac04\uc758 \uade0\ud615\uc744 \ub3c4\ubaa8\ud558\uc600\ub2e4","\uc9c4\ub300\ubc95\uc744 \uc2e4\uc2dc\ud558\uc5ec \ube48\ubbfc\uc744 \uad6c\uc81c\ud558\uc600\ub2e4"],t.s)
