B.asm=new A.b("gen_kh_js1_16","korean_history","\uc870\uc120\uc804\uae30","\uc0ac\ub9bc\uc758 \uc131\uc7a5\uacfc \uc0ac\ud654\xb7\ubd95\ub2f9","\uc744\uc0ac\uc0ac\ud654\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.IZ,0,"\uc744\uc0ac\uc0ac\ud654(1545)\ub294 \uba85\uc885\uc774 \uc5b4\ub9b0 \ub098\uc774\uc5d0 \uc989\uc704\ud558\uba74\uc11c \uc678\ucc99\uc778 \uc724\uc784(\ub300\uc724)\uacfc \uc724\uc6d0\ud615(\uc18c\uc724) \uc138\ub825 \uac04\uc758 \uad8c\ub825 \ub2e4\ud23c \uc18d\uc5d0\uc11c \uc0ac\ub9bc\uc774 \ub2e4\uc2dc \ud070 \ud654\ub97c \uc785\uc740 \uc0ac\uac74\uc774\ub2e4. \u300c\uc870\uc758\uc81c\ubb38\u300d\uc740 \ubb34\uc624\uc0ac\ud654, \uc870\uad11\uc870 \uac1c\ud601 \ubc18\ubc1c\uc740 \uae30\ubb18\uc0ac\ud654, \ud3d0\ube44 \uc0ac\uac74\uc740 \uac11\uc790\uc0ac\ud654, \uacbd\uc2e0\ud658\uad6d\uc740 \uc219\uc885 \ub300 \ubd95\ub2f9 \uc815\uce58\uc758 \uc0ac\uac74\uc774\ub2e4.",B.VV,B.aar,null)
B.aaU=s([u.oi,"\uc11c\uc6d0\uc740 \uad6d\uac00\uac00 \uc124\ub9bd\ud558\uc5ec \uc9c0\ubc29\uad00\uc774 \uc6b4\uc601\uc744 \uac10\ub3c5\ud55c \uad00\ud559\uc774\uc5c8\ub2e4","\ud5a5\uc57d\uc740 \uad6d\uac00\uac00 \uc81c\uc815\ud558\uc5ec \uc804\uad6d\uc5d0 \uac15\uc81c\ub85c \uc2dc\ud589\ud55c \ubc95\ub960\uc774\ub2e4","\ud5a5\uc57d\uc740 \uc0bc\uad6d\uc2dc\ub300\ubd80\ud130 \uc2dc\ud589\ub41c \ucd0c\ub77d \uacf5\ub3d9\uccb4 \uaddc\uc57d\uc774\ub2e4","\uc11c\uc6d0\uacfc \ud5a5\uc57d\uc740 \ubaa8\ub450 \ud6c8\uad6c \uc138\ub825\uc774 \ud5a5\ucd0c \uc9c0\ubc30\ub97c \uc704\ud574 \ub9cc\ub4e0 \uc81c\ub3c4\uc774\ub2e4"],t.s)
