B.aCT=new A.b("gen_kh_js1_17","korean_history","\uc870\uc120\uc804\uae30","\uc0ac\ub9bc\uc758 \uc131\uc7a5\uacfc \uc0ac\ud654\xb7\ubd95\ub2f9","\uc870\uc120 \uc2dc\ub300 \uc11c\uc6d0\uacfc \ud5a5\uc57d\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aaU,0,"\uc11c\uc6d0\uc740 \uc0ac\ub9bc\uc774 \uac01 \uc9c0\ubc29\uc5d0 \uc138\uc6b4 \uc0ac\ub9bd \uad50\uc721 \uae30\uad00\uc73c\ub85c \uc120\ud604\uc5d0 \ub300\ud55c \uc81c\uc0ac\uc640 \uc131\ub9ac\ud559 \uc5f0\uad6c\xb7\uad50\uc721\uc744 \uacb8\ud558\uc600\uc73c\uba70(\ucd5c\ucd08\uc758 \uc11c\uc6d0\uc740 \ubc31\uc6b4\ub3d9 \uc11c\uc6d0), \ud5a5\uc57d\uc740 \uc0ac\ub9bc\uc774 \uc720\uad50 \uc724\ub9ac\ub97c \ubc14\ud0d5\uc73c\ub85c \ud5a5\ucd0c \uc790\uce58\ub97c \uc704\ud574 \ubcf4\uae09\ud55c \uaddc\uc57d\uc73c\ub85c, \uc11c\uc6d0\uacfc \ud5a5\uc57d \ubaa8\ub450 \uc0ac\ub9bc\uc774 \ud5a5\ucd0c \uc0ac\ud68c\uc5d0\uc11c \uc601\ud5a5\ub825\uc744 \ud655\ub300\ud558\ub294 \uae30\ubc18\uc774 \ub418\uc5c8\ub2e4.",B.Ux,B.aeb,null)
B.WF=s(["\uc774\uc870 \uc804\ub791 \uc784\uba85 \ubb38\uc81c\ub97c \ub458\ub7ec\uc2f8\uace0 \uc0ac\ub9bc\uc774 \ub3d9\uc778\uacfc \uc11c\uc778\uc73c\ub85c \ub098\ub258\uc5c8\ub2e4","\uc219\uc885 \ub300 \uacbd\uc2e0\ud658\uad6d\uc744 \uacc4\uae30\ub85c \ucc98\uc74c \ubd95\ub2f9\uc774 \ud615\uc131\ub418\uc5c8\ub2e4","\uc601\uc870\uac00 \ud0d5\ud3c9\ucc45\uc744 \uc2e4\uc2dc\ud558\uba70 \ubd95\ub2f9\uc774 \ucc98\uc74c \ub098\ud0c0\ub0ac\ub2e4","\ubb34\uc2e0\uc815\ubcc0 \uc774\ud6c4 \ubb38\uc2e0\ub4e4\uc774 \ub3d9\uc778\uacfc \uc11c\uc778\uc73c\ub85c \uac08\ub77c\uc84c\ub2e4","\uac11\uc624\uac1c\ud601 \uacfc\uc815\uc5d0\uc11c \uac1c\ud654\ud30c\uac00 \ub3d9\uc778\uacfc \uc11c\uc778\uc73c\ub85c \ubd84\ud654\ub418\uc5c8\ub2e4"],t.s)
