B.aCr=new A.b("gen_kh_js1_18","korean_history","\uc870\uc120\uc804\uae30","\uc0ac\ub9bc\uc758 \uc131\uc7a5\uacfc \uc0ac\ud654\xb7\ubd95\ub2f9","\uc120\uc870 \ub300 \ubd95\ub2f9\uc758 \ud615\uc131\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.WF,0,"\uc120\uc870 \ub300\uc5d0 \uc0ac\ub9bc\uc774 \uc911\uc559 \uc815\uacc4\ub97c \uc7a5\uc545\ud55c \uc774\ud6c4, \uc774\uc870 \uc804\ub791(\uc778\uc0ac\uad8c\uc5d0 \uad00\uc5ec\ud558\ub294 \uc694\uc9c1)\uc758 \uc784\uba85 \ubb38\uc81c\ub97c \ub458\ub7ec\uc2f8\uace0 \uae40\ud6a8\uc6d0\uc744 \uc9c0\uc9c0\ud558\ub294 \ub3d9\uc778\uacfc \uc2ec\uc758\uacb8\uc744 \uc9c0\uc9c0\ud558\ub294 \uc11c\uc778\uc73c\ub85c \ub098\ub258\uba74\uc11c \ubd95\ub2f9 \uc815\uce58\uac00 \uc2dc\uc791\ub418\uc5c8\ub2e4.",B.a0o,B.Pp,null)
B.P3=s([u.lh,"\uccad\uacfc\ub294 \uc0ac\ub300 \uad00\uacc4\ub97c, \uba85\uacfc\ub294 \uad50\ub9b0 \uad00\uacc4\ub97c \ub9fa\uc5c8\ub2e4","\uc77c\ubcf8\uacfc\ub294 \ud1b5\uc2e0\uc0ac\ub97c \ud30c\uacac\ud558\uc9c0 \uc54a\uace0 \uad50\ub958\ub97c \ub2e8\uc808\ud558\uc600\ub2e4","\uc5ec\uc9c4\uacfc\ub294 \ubb34\uc5ed\uc744 \uc804\uba74 \uae08\uc9c0\ud558\uace0 \uad6d\uacbd\uc744 \ubd09\uc1c4\ud558\uc600\ub2e4","\uba85\uacfc \ub300\ub4f1\ud55c \uad00\uacc4\ub97c \ub9fa\uace0 \uc870\uacf5\xb7\ucc45\ubd09 \uad00\uacc4\ub97c \uac70\ubd80\ud558\uc600\ub2e4"],t.s)
