B.auu=new A.b("gen_kh_js1_19","korean_history","\uc870\uc120\uc804\uae30","\ub300\uc678\uad00\uacc4\uc640 \uc784\uc9c4\uc65c\ub780","\uc870\uc120 \uc804\uae30\uc758 \ub300\uc678 \uad00\uacc4\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.P3,0,"\uc870\uc120 \uc804\uae30\ub294 \uba85\uacfc\ub294 \uc0ac\ub300 \uad00\uacc4\ub97c \uc720\uc9c0\ud558\uba70 \uc120\uc9c4 \ubb38\ubb3c\uc744 \uc218\uc6a9\ud558\uace0, \uc5ec\uc9c4\xb7\uc77c\ubcf8 \ub4f1 \uc8fc\ubcc0\uad6d\uacfc\ub294 \uad50\ub9b0 \uad00\uacc4\ub97c \ub9fa\uc5b4 \ud68c\uc720\uc640 \uac15\uacbd\ucc45\uc744 \ubcd1\ud589\ud558\ub294 \uc0ac\ub300\uad50\ub9b0\uc744 \uae30\ubcf8 \uc678\uad50 \uc815\ucc45\uc73c\ub85c \uc0bc\uc558\ub2e4. \uc774\uc5d0 \ub530\ub77c \uc77c\ubcf8\uc5d0\ub294 \ud1b5\uc2e0\uc0ac\ub97c \ud30c\uacac\ud558\uace0, 3\ud3ec(\ubd80\uc0b0\ud3ec\xb7\uc81c\ud3ec\xb7\uc5fc\ud3ec)\ub97c \uac1c\ud56d\ud558\uc5ec \uc81c\ud55c\uc801 \ubb34\uc5ed\uc744 \ud5c8\uc6a9\ud558\uc600\ub2e4.",B.Ui,B.afC,null)
B.ahu=s(["\uc784\uc9c4\uc65c\ub780 3\ub300 \ub300\ucca9 \uc911 \ud558\ub098\ub85c, \ub0a8\ud574\uc758 \uc81c\ud574\uad8c\uc744 \uc7a5\uc545\ud558\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4","\uac70\ub780\uc758 3\ucc28 \uce68\uc785\uc744 \ubb3c\ub9ac\uce5c \uc804\ud22c\uc600\ub2e4","\ubabd\uace8\uc758 \uce68\uc785\uc5d0 \ub9de\uc11c \ucc98\uc778\uc131\uc5d0\uc11c \ubc8c\uc5b4\uc9c4 \uc804\ud22c\uc600\ub2e4","\uc5ec\uc9c4\uc744 \uc815\ubc8c\ud558\uae30 \uc704\ud574 \ubcc4\ubb34\ubc18\uc774 \ub3d9\uc6d0\ub41c \uc804\ud22c\uc600\ub2e4","\uc65c\uad6c\ub97c \ubb3c\ub9ac\uce5c \ucd5c\uc601\uc758 \ud64d\uc0b0 \ub300\ucca9\uc774\uc5c8\ub2e4"],t.s)
B.L6=s(["\uc784\uc9c4\uc65c\ub780 3\ub300 \ub300\ucca9 \uc911 \ud558\ub098\ub85c, \ub0a8\ud574\uc758 \uc81c\ud574\uad8c\uc744 \uc7a5\uc545\ud558\ub294 \uacc4\uae30\uac00 \ub418\uc5c8\ub2e4"],t.s)
